WITH payload AS (SELECT $archive_payload$[{"id":"2c25e4ef-73e2-5f1e-9e4a-512e54864343","document_type":"judgment","category":"judicial","subcategory":"general","title":"وقف -إجارة وقف -تعويض عن طرد مستأجرين -إنكار -قيام املدعي «ناظر الوقف» بتأجير العقار بعد التصرف الضار -احلكم بصرف النظر لزوال الضرر -رفع احلكم حملكمة الاستئناف لتعلقه","document_number":"3449861","case_number":"32571584","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":"الدائرة املدعي هل قام بتأجير الشقق فأجاب بأنه قام بتأجير","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/27","year":"1434","subject":"وقف -إجارة وقف -تعويض عن طرد مستأجرين -إنكار -قيام املدعي «ناظر الوقف» بتأجير العقار بعد التصرف الضار -احلكم بصرف النظر لزوال الضرر -رفع احلكم حملكمة الاستئناف لتعلقه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/2/27 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3449861 :‬‬\n                        ‫َر ْق ُم الدعوى‪32571584 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34181960‬تاريخه‪1434/4/8 :‬هـ‬\n\n\n     ‫وقــف ‪ -‬إجــارة وقــف ‪ -‬تعويــض عــن طــرد مســتأجرين ‪ -‬إنــكار ‪ -‬قيــام‬\n     ‫املدعــي «ناظــر الوقــف» بتأجيــر العقــار بعــد التصــرف الضــار ‪ -‬احلكــم‬\n     ‫بصــرف النظــر لــزوال الضــرر ‪ -‬رفــع احلكــم حملكمــة االســتئناف لتعلقــه‬\n                                                                           ‫بوقــف‪.‬‬\n\n\n\n     ‫‪ .1‬الضمــان ال يجــب مبجــرد حــدوث الفعــل الضــار بــل إن مــن شــرطه‬\n     ‫أن يكــون حتقــق وقــوع الضــرر بصفــة دائمــة وذلــك بــأن يتحقــق العجــز‬\n            ‫عــن االنتفــاع علــى طريــق الــدوام‪ .‬بدائــع الصانــع ‪.157-1554/7‬‬\n     ‫‪ .2‬مــا نقلــه ابــن قدامــة يف املغنــي عــن القاضــي أبــي يعلــى مــن قولــه‪:‬‬\n     ‫«إذا ســقطت أخواتهــا ولــم تعــد أخــذت الديــة وإن نبــت مكانهــا أخــرى لــم‬\n                       ‫جتــب ديتهــا كمــا لــو نتــف شــعره فعــاد مثلــه» ‪.133/12‬‬\n                                                    ‫‪ )165( .3‬من نظام املرافعات‪.‬‬\n\n\n\n\n     ‫تقــدم املدعــي بصفتــه ناظــر وقــف بدعــواه ضــد املدعــى عليهمــا بأنهمــا‬\n     ‫قامــا بإخــراج املســتأجرين مــن بعــض الشــقق وطلــب احلكــم عليهمــا‬\n     ‫بالتعويــض لقــاء مــا بــدر منهمــا‪ ،‬أنكــر املدعــى عليهمــا الدعوى‪،‬ســألت‬\n     ‫الدائــرة املدعــي هــل قــام بتأجيــر الشــقق فأجــاب بأنــه قــام بتأجيــر‬\n\n‫‪69‬‬\n\f‫الشــقق محــل الدعــوى‪ ،‬فبنــاء علــى مــا تقــدم ولطلــب املدعــي احلكــم‬\n‫علــى املدعــى عليهمــا بدفــع تعويــض عــن الشــقق األربــع التــي تضــرر‬\n‫الوقــف بخــروج املســتأجرين منهــا كمــا ادعــى‪ ،‬وإلقــراره بــأن تلــك‬\n‫الشــقق األربــع قــد مت تأجيرهــا‪ ،‬وألن الضمــان ال يجــب مبجــرد حــدوث‬\n‫الفعــل الضــار بــل مــن شــروطه حتقــق وقــوع الضــرر بصفــة دائمــة وذلــك‬\n‫بــأن يتحقــق العجــز عــن اإلنتفــاع دومــا انظــر بدائــع الصنائــع ‪-1554/7‬‬\n‫‪ ،157‬عليــه فــإذا رجــع الشــيء إلــى احلالــة التــي كان عليهــا فــا ضمــان‬\n‫ألن صاحــب احلــق اســتطاع االنتفــاع بحقــه علــى الوجــه الــذي كان عليــه‬\n‫قبــل حــدوث الضــرر جــاء يف املغنــي البــن قدامــة يف معــرض حديثــه عــن‬\n‫ديــة األســنان (ويف كل ســن خمــس مــن اإلبــل) وقــال القاضــي (إذا‬\n‫ســقطت أخواتهــا ولــم تعــد أخــذت الديــة وإن نبــت مكانهــا أخــرى لــم‬\n‫جتــب ديتهــا كمــا لــو نتــف شــعره فعــاد مثلــه) ‪ 133/12‬فيقــاس عليــه‬\n‫أي ضــرر‪ ،‬يشــترط الســتحقاق التعويــض عنــه وقوعــه بصفــة دائمــة فــإذا‬\n‫رجــع الشــيء إلــى احلالــة التــي كان عليهــا فــا تعويــض‪ ،‬صــدر احلكــم‬\n‫بصــرف النظــر عــن دعــوى املدعــي وإخــاء ســبيل املدعــى عليهمــا منهــا‪،‬‬\n‫بعرضــه علــى املدعــي قــرر قناعتــه بــه واســتناد ًا علــى املــادة اخلامســة‬\n‫والســتني بعــد املائــة مــن نظــام املرافعــات الشــرعية فقــد قــررت رفــع‬\n‫كامــل أوراق املعاملــة إلــى محكمــة االســتئناف لتدقيــق احلكــم لتعلقــه‬\n                         ‫بوقــف‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                   ‫‪70‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي باحملكمــة العامــة‬\n     ‫ـاء علــى أوراق املعاملــة احملالــة الينــا مــن فضيلــة‬\n                                                           ‫مبكــة املكرمــة وبنـ ً‬\n     ‫رئيــس هــذه احملكمــة برقــم ‪ 32571584‬يف ‪1432/12/2‬ه ـ واملقيــدة‬\n     ‫برقــم ‪ 321546749‬يف ‪1432/12/2‬ه ـ املتعلقــة بدعــوى(‪ ).....‬ضــد‬\n     ‫(‪ ).....‬و(‪ ).....‬بنــاء علــى ذلــك فقــد حضــر لــدي يف هــذا اليــوم األحــد‬\n     ‫‪1433/11/28‬ه ـ الســاعة ‪ 10 : 00‬املدعــى (‪ ).....‬بالســجل املدنــي‬\n     ‫رقــم (‪ ).....‬بالوكالــة عــن (‪ ).....‬برقــم ‪ 30111‬يف ‪1432/10/27‬ه ـ‬\n     ‫الصــادرة مــن كاتــب عــدل مكــة املكرمــة وحضــر حلضــوره املدعــي‬\n     ‫(‪ ).....‬وحضــر حلضورهمــا املدعــى عليهــا كل مــن (‪ ).....‬بالســجل املدنــي‬\n     ‫(‪ ).....‬و(‪ ).....‬بالســجل املدنــي (‪ ).....‬ثــم ادعــى املدعــي أصالــة يف مواجهــة‬\n     ‫املدعــى عليهمــا قائــا يف حتريــر دعــواه إنــه ســبق وأن أبرمــت عقــد ًا‬\n     ‫بصفتــي ناظــر ًا علــى وقــف (‪ ).....‬مــع عــدد مــن املســتأجرين يف عقــار‬\n     ‫للوقــف املذكــور الكائــن يف (‪ ).....‬خلــف (‪ ).....‬الثابــت وقفيتــه مبوجــب‬\n     ‫صــك الوقفيــة رقــم ‪ 6/100/352‬يف ‪1430/7/11‬ه ـ الصــادر مــن هــذه‬\n     ‫احملكمــة والــذي جعلــت ناظــر ًا عليــه مبوجــب الصــك الصــادر مــن هــذه‬\n     ‫احملكمــة برقــم ‪ 22329668‬يف ‪1432/11/21‬ه ـ حيــث قمــت بتأجيــر‬\n     ‫أربــع شــقق مــن ذلــك العقــار علــى أربعــة مســتأجرين يف ‪1432/10/15‬هـ‬\n     ‫غيــر أن املدعــى عليهمــا قامــا بإخــراج املســتأجرين األربعــة مــن شــققهم‬\n     ‫بــدون حجــة حيــث لــم يبــق ثالثــة منهــم يف األعيــان املؤجــرة عليهــم ســوى‬\n     ‫يومــن أو ثالثــة والرابــع لــم يــزد علــى خمســة عشــر يومـ ًا فقــط مــن تاريــخ‬\n     ‫عقــد اإليجــار معهــم وقــام كذلــك بإعــادة كامــل األجــرة التــي قامــوا‬\n\n‫‪71‬‬\n\f‫بدفعهــا وذلــك بــدون مســوغ وال مبــرر مــا عــاد علــى الوقــف ومســتحقيه‬\n‫بالضــرر البالــغ لــذا فإنــي أطلــب احلكــم عليهمــا بدفــع تعويــض عــن تلــك‬\n‫الشــقق األربعــة التــي تضــرر الوقــف بخــروج املســتأجر منهــا وأســألهم‬\n‫اجلــواب وبعــرض ذلــك علــى املدعــى عليهمــا أبــرز املدعــى عليــه ‪ ...‬محــررا‬\n‫قــرر أنــه جــواب لــه وباالطــاع عليــه وجدتــه يتضمــن ((لقــد مت االطــاع‬\n‫علــي الشــكوى املقدمــة مــن (‪ ).....‬بتاريــخ بــدون والغيــر صحيحــة والغيــر‬\n‫واضــح مــا يدعــي فيهــا والصحيح هو أن الوالــد تويف يوم ‪1432/6/11‬هـ‬\n‫وأن الشــكوى كيديــه ليــس لهــا أســاس مــن الصحــة وأفــاد يف شــكواه‬\n‫أنــه اجتمــع مــع الورثــة يف هــذا اخلصــوص وهــذا غيــر صحيــح وكان ذلك‬\n‫لفــك الــورث ولــم يحصــل فــك اإلرث حتــى تاريخــه إذ لــم يتــم االجتمــاع‬\n‫واالطــاع علــى شــيء وانــه قــام بإيجــار الشــقق بتاريــخ ‪1432/10/16‬ه ـ‬\n‫حســب مــا يتضــح لكــم مــن مكتــب العقــار ولــم ميلــك صــك للنظــارة إال‬\n‫يف تاريــخ ‪1432/11/13‬ه ـ وبهــذا ال يحــق لــه ايجــار عقــار الوقــف إال‬\n‫بعــد صــدور صــك النظــارة وهــذا مــا يتضــح مــن صــك النظــارة وأفهــم بــه‬\n‫وذلــك ســبب تدخــل رجــال األمــن حيــث يوجــد يف صــك الوقفيــة شــروط‬\n‫للموقــف لــم يطلــع عليهــا الناظــر مبــا إننــي كنــت الشــاهد الوحيــد علــى‬\n‫صــك الوقفيــة وهــذا مــا يتضــح لكــم يف صــك الوقفيــة وامــا بخصــوص‬\n‫محضــر رجــال األمــن عمــل رســمي وســجل يف قســم العزيزيــة وميكــن‬\n‫طلبــه منهــم وأمــا بخصــوص الشــقة اخلامســة وحســب كالم املدعــي انــه‬\n‫أجرهــا علــى اختــه (‪ ).....‬وكان قبلهــا يقــول أن الشــقة لوالدتــك وحســب‬\n‫كالم ومــا ســمعته مــن (‪ ).....‬أنــا عرضنــا عليــه االيجــار بعــد النظــارة‬\n‫ورفــض برغــم أن لنــا الشــفعة يف ذلــك وحســب كالم (‪ ).....‬ســوء ســمعة‬\n‫العمــارة عنــد مكاتــب (‪).....‬كيــف مت إيجــار العمــارة وهــل هــي مؤجــرة‬\n\n\n                                                                                    ‫‪72‬‬\n\f     ‫اآلن أو ال لــذا أطلــب بإحالــة املوضــوع إلــى االدعــاء العــام للتحقيــق يف‬\n     ‫املوضــوع وإظهــار احلــق وحســب كالم (‪ ).....‬أنــه وصــي علــى الناظــر‬\n     ‫والورثــة أطلــب احلضــور مــن الورثــة والســماع منهــم مبــا يقــول واســتخدام‬\n     ‫الــوكاالت بطريقــه غيــر صحيحــة والشــكوات الكيديــة ومحاســبته‬\n     ‫حيــث تبلــغ مــن الورثــة أن الــوكاالت التــي ســلمت لــه لفــك اإلرث وليــس‬\n     ‫لشــكايات كيديــة وتفكيــك األســرة ومت منعنــا مــن مخاطبــة الوالــدة‬\n     ‫أو مقابلتهــا أو اجللــوس معهــا بإنفــراد ومنعهــا مــن زيارتنــا بــدون أســباب‬\n     ‫أو مبــررات بحجــة انــه الوكيــل)) إ‪.‬هــ‪ .‬كمــا قــدم املدعــى عليــه اآلخــر‬\n     ‫(‪ ).....‬جوابــا محــررا تضمــن (( إن اإلجــراء الــذي أتخذه شــقيقي (‪ ).....‬يف‬\n     ‫إيجــار وقــف مورثنــا (‪( ).....‬رحمــه اهلل) غيــر صحيــح لألســباب التاليــة‬\n     ‫وهــي أنــه لــم ينفــذ وصيــة والــدي وذلــك حســب صــك الوقــف وليــس لديــه‬\n     ‫وكاالت مــن اجلميــع حتــى تتماشــي مــع األنظمــة وتوحــد اجلهــود يف‬\n     ‫عمليــة اإليجــارات وتســد املزايــدات ولــم تكــن اإلجــراءات التــي يقــوم‬\n     ‫بهــا واضحــة للجميــع ولــم يجتمــع بجميــع الورثــة وهــم أشــقاءه (أربعــة‬\n     ‫ذكــور وثالثــة إنــاث إضافــة إلــى والدتنــا الكبيــرة بالســن) كمــا ورد‬\n     ‫يف دعــواه وال أعــرف مــا هــي بنــود االتفــاق وخاصة يف اســتالم اإليجارات‬\n     ‫وتوزيعهــا ومتــى كمــا ورد يف دعــواه أنــه مت االتفــاق لذلــك قمنــا بإفهامــه‬\n     ‫وكانــت ردة فعلــه اســتخراجه لصــك النظــارة والتقــدمي بهــذه الدعــوى‬\n     ‫وحتــى اآلن لــم يقــم بواجــب النظــارة ولــم يســتطع إيجــار خمــس شــقق‬\n     ‫بحــي (‪ ).....‬خلــف (‪ ).....‬وبــدا يلقــي باللــوم علينــا حتــى يحصــل علــى‬\n     ‫عــذر عــدم إيجــار الشــقق مــع العلــم إن طلــب الشــقق بهــذه املنطقــة التــي‬\n     ‫ال يخفــى علــى أحــد مطلوبــة كمــا أن اســتخراج صــك النظــارة وأفــاد‬\n     ‫الورثــة مــن حيــث تنفيــذ مــا ورد بصــك الوقــف وااللتــزام مبــا ورد يف صك‬\n\n\n‫‪73‬‬\n\f‫نظارتــه ووضــوح اإلجــراءات للجميــع أفــاد املدعــي محاســبتنا وتكليفنــا‬\n‫بجميــع خســائرهم ولــم يعمــل كشــف حســاب يوضــح خســائرهم وهــذا‬\n‫يــدل علــى عــدم مصداقيتــه عليــه أطلــب مــن فضيلتكــم تكليفــه‬\n‫بعمــل كشــف خســائره التــي أدعهــا ومحاســبة املتســبب بهــا وكذلــك‬\n‫كشــف حســاب الوقــف بالتواريــخ منــذ أن نصــب نفســه ناظــرا مــع‬\n‫العلــم أننــي لــم أتســلم أي مســتحقات مــن تاريــخ ‪1432/6/11‬ه ـ وأمــل‬\n‫أن تســلم لنــا عــن طريــق قنــوات رســمية أمــا بالنســبة للشــقة اخلامســة‬\n‫فهــي مســكونة وفيهــا أثــاث وميكــن لفضيلتكــم إرســال أي منــدوب‬\n‫للوقــوف عليهــا وطلــب فواتيــر الكهربــاء مــن بعــد تاريــخ وفــاة مورثنــا‬\n‫وقــد صــدر حكــم بذلــك مــن فضيلــة القاضــي الشــيخ (‪ ).....‬بصــك‬\n‫رقــم ‪ 33213511‬وتاريــخ ‪1433/4/26‬ه ـ والصــادر مــن هــذه احملكمــة‬\n‫والزالــت املماطلــة قائمــة يف تأجيرهــا أطلــب مــن فضيلتكــم اإلثباتــات‬\n‫مــن مقــدم الدعــوى وحضــور الورثــة الــذي اجتمــع بهــم للوقــوف علــى‬\n‫االتفــاق ويف حالــة عــدم ثبــوت مصداقيــة املدعــي يعاقــب علمــا بأننــي‬\n‫متضــرر معنويــا وماديــا مــن هــذا اإلدعــاء الــذي أضــاع علينــا اجلهــد‬\n‫والوقــت كمــا أطلــب اســتحقاقي للفتــرة التــي ســكن فيهــا املســتأجرين‬\n‫اللذيــن خرجــوا وتعويضنــا باخلســائر التــي ذكرهــا املدعــي يف شــكواه‬\n‫)) إ‪.‬هــ‪ .‬ثــم ســألت املدعــي هــل مت تأجيــر الشــقق األربــع بعــد أن خــرج‬\n‫منهــا املســتأجرون األربعــة ومتــى كان فأجــاب بقولــه نعــم لقــد مت‬\n‫تأجيــر الشــقق األربــع حيــث قمــت بتأجيرهــا واآلن يقطنهــن مســتأجرون‬\n‫جــدد ثــم ســألت املدعــي عــن عقــود اإليجــار املبرمــة فأبــرز أربعــة عقــود‬\n‫مبرمــة مــع أربعــة مســتأجرين أرفــق صورهــا باملعاملــة ثــم جــرى تصفــح‬\n‫أوراق املعاملــة فوجــدت صــورة صــك صــادر مــن هــذه احملكمــة برقــم‬\n\n\n                                                                                    ‫‪74‬‬\n\f     ‫‪ 32329668‬يف ‪1432/11/21‬ه ـ ويتضمــن إقامــة (‪ ).....‬ناظــر علــى‬\n     ‫وقــف (‪).....‬كذلــك وجــدت ضمــن طياتهــا صــورة صــك إثبــات وقفيــة‬\n     ‫برقــم ‪ 6/100/352‬يف ‪1430/07/11‬ه ـ ويتضمــن وقفيــة (‪ ).....‬وهــو‬\n     ‫بكامــل األهليــة الشــرعية وحبــس وســبل وتصــدق وأكــد وخلــد مــا هــو‬\n     ‫يف مكــة وحوزتــه وهــو باقــي حتــت تصرفــه واختصاصــه مبفــرده إلــى‬\n     ‫حــن صــدور الوقــف وهــو كامــل األرض ومــا أنشــأ عليهــا مــن مبانــي‬\n       ‫وقــف صحيح ـ ًا شــرعي ًا وحبس ـ ًا صريح ـ ًا مرعي ـ ًا أ‪.‬هــ‪ .‬هــذا مــا وجدتــه‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء ‪1434/02/05‬ه ـ‬\n     ‫الســاعة ‪ 10: 45‬وفيهــا حضــر املتداعــون فبنــاء علــى مــا تقــدم مــن‬\n     ‫الدعــوى واإلجابــة ولطلــب املدعــي احلكــم علــى املدعــى عليهمــا بدفــع‬\n     ‫تعويــض عــن الشــقق األربــع التــي تضــرر الوقــف بخــروج املســتأجرين‬\n     ‫منهــا كمــا قــال وإلقــراره بــأن تلــك الشــقق األربــع قــد مت تأجيرهــا وألن‬\n     ‫الضمــان ال يجــب مبجــرد حــدوث الفعــل الضــار بــل إن مــن شــروطه أن‬\n     ‫يكــون حتقــق وقــوع الضــرر بصفــة دائمــة وذلــك بــأن يتحقــق العجــز‬\n     ‫عــن اإلنتفــاع علــى طريــق الــدوام أنظــر بدائــع الصنائــع ‪157-1554/7‬‬\n     ‫وعليــه فــإذا رجــع الشــيء إلــى احلالــة التــي كان عليهــا فــا ضمــان ألن‬\n     ‫صاحــب احلــق اســتطاع االنتفــاع بحقــه علــى الوجــه الــذي كان عليــه‬\n     ‫قبــل حــدوث الضــرر جــاء يف املغنــي إلبــن قدامــة يف معــرض حديثــه عــن‬\n     ‫ديــة األســنان فيشــرح قــول اخلرقــي رحمــه اهلل (ويف كل ســن خمــس‬\n     ‫مــن اإلبــل) وقــال القاضــي (إذا ســقطت أخواتهــا ولــم تعــد أخــذت الديــة‬\n     ‫وإن نبــت مكانهــا أخــرى لــم جتــب ديتهــا كمــا لــو نتــف شــعره فعــاد‬\n     ‫مثلــه) ‪ 133/12‬فيقــاس علــى هــذا أن أي ضــرر مــن شــرط اســتحقاق‬\n     ‫التعويــض عنــه وقوعــه بصفــة دائمــة فــإذا رجــع الشــيء إلــى احلالــة التــي‬\n\n\n‫‪75‬‬\n\f‫كان عليهــا فــا تعويــض بنــاء عــل ذلــك فقــد صرفــت النظــر عــن دعــوى‬\n‫املدعــي وأخليــت ســبيل املدعــى عليهمــا منهــا وبذلــك حكمــت وبعرضــه‬\n‫علــى املدعــي قــرر قناعتــه بــه عليــه واألمــر مــا ذكــر واســتناد ًا علــى املادة‬\n‫اخلامســة والســتني بعــد املائــة مــن نظــام املرافعــات الشــرعية فقــد قــررت‬\n‫رفــع كامــل أوراق املعاملــة إلــى محكمــة اإلســتئناف لتدقيــق احلكــم‬\n‫لتعلقــه بوقــف وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                    ‫وصحبــه وســلم ‪ .‬حــرر يف‪1434/2/5‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ ).....‬القاضــي باحملكمــة العامــة‬\n‫مبكــة املكرمــة خلــف فضيلــة الشــيخ (‪ ).....‬القاضــي األســبق بهــذه‬\n‫احملكمــة حيــث عــادت أوراق املعاملــة مــن محكمــة االســتئناف‬\n‫باخلطــاب رقــم ‪ 321546749‬يف ‪1434/4/15‬ه ــرفقها الصــك الشــرعي‬\n‫رقــم ‪ 3449861‬يف ‪1434/2/27‬ه ـ مظهــر ًا عليــه بقــرار الدائــرة‬\n‫الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت‬\n‫املــال مبحكمــة االســتئناف مبكــة املكرمــة رقــم ‪ 34181960‬يف‬\n‫‪1434/4/8‬ه ـ املتضمــن أنــه بدراســة الصــك وصــورة ضبطــه تقــررت‬\n‫املوافقــة علــى احلكــم قاضــي اســتئناف ختــم وتوقيــع(‪ ).....‬قاضــي‬\n‫اســتئناف ختــم وتوقيــع (‪ ).....‬رئيــس الدائــرة ختــم وتوقيــع (‪ ).....‬حــرر يف‬\n‫‪1434/6/6‬ه ـ وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪..‬‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة‬\n‫مكــة املكرمــة االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ(‪).....‬‬\n‫القاضــي باحملكمــة العامــة مبكــة املكرمــة برقــم ‪ 3449861‬وتاريــخ‬\n\n\n                                                                                          ‫‪76‬‬\n\f     ‫‪1434/2/27‬ه ـ املتضمــن دعــوى (‪ ).....‬ضــد (‪ ).....‬و(‪ ).....‬ابنــي (‪).....‬‬\n     ‫بخصــوص أضــرار بالوقــف املذكــور يف اإلنهــاء وبدراســة الصــك‬\n     ‫وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n                                    ‫علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪77‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":69,"source_page_end":77,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"02ad3d7acb1bf988ec16a53eb4014bb8b0fbdb0b737a38e883b4c577dcad6f10","normalized_text_hash":"7f155dea548a243a9a0146a45663ccda3bc6980168391ccccd32f15ba3b5c687","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p69-3449861"},{"id":"d86899de-2578-57f2-88b0-cab4085b8ece","document_type":"judgment","category":"judicial","subcategory":"general","title":"وقف -عقد استثمار وقف -نزع ملكية الوقف -مطالبة بالتعويض عن مدة العقد -وجوب الوفاء بالعقود -سريان مفعول صك النظارة -التعويض املقدر لأرض يكون للوقف والتعويض املقدر للمبنى يوزع على عدد سنوات عقد اإليجار -وجوب رفع احلكم حملكمة الاستئناف إذا كان احملكوم عليه ناظر وقف ولو قنع.","document_number":"34311046","case_number":"34186030","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/2","year":"1434","subject":"وقف -عقد استثمار وقف -نزع ملكية الوقف -مطالبة بالتعويض عن مدة العقد -وجوب الوفاء بالعقود -سريان مفعول صك النظارة -التعويض املقدر لأرض يكون للوقف والتعويض املقدر للمبنى يوزع على عدد سنوات عقد اإليجار -وجوب رفع احلكم حملكمة الاستئناف إذا كان احملكوم عليه ناظر وقف ولو قنع.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/9/2 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34311046 :‬‬\n                   ‫َر ْق ُم الدعوى‪34186030 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34385607‬تاريخه‪1434/12/24 :‬هـ‬\n\n\n‫وقــف ‪ -‬عقــد اســتثمار وقــف ‪ -‬نــزع ملكيــة الوقــف ‪ -‬مطالبــة بالتعويــض‬\n‫عــن مــدة العقــد ‪-‬وجــوب الوفــاء بالعقــود ‪ -‬ســريان مفعــول صــك‬\n‫النظــارة ‪ -‬التعويــض املقــدر لــأرض يكــون للوقــف والتعويــض املقــدر‬\n‫للمبنــى يــوزع علــى عــدد ســنوات عقــد اإليجــار ‪ -‬وجــوب رفــع احلكــم‬\n    ‫حملكمــة االســتئناف إذا كان احملكــوم عليــه ناظــر وقــف ولــو قنــع‪.‬‬\n\n\n\n\n                     ‫‪ .1‬قوله تعالى {يا أيها الذين آمنوا أوفوا بالعقود}‪.‬‬\n                 ‫‪ .2‬قوله صلى اهلل عليه وسلم (املسلمون على شروطهم)‪.‬‬\n                           ‫‪ .3‬املادة (‪ )179‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n‫ادعــى املدعــي ضــد ناظــري وقــف بأنــه اســتثمر عقــار الوقــف الواقــع‬\n‫يف ‪ ...‬مبوجــب الصــك الصــادر مــن هــذه احملكمــة واســتلم العقــار‬\n‫بتاريــخ ‪1419/1/21‬ه ـ ملــدة خمســة عشــر عام ـ ًا وقــد أزيــل الوقــف‬\n‫بتاريــخ ‪1431/1/15‬ه ـ بعــد مضــي اثنــا عشــر عامــا وتبقــي لــه مــن مــدة‬\n‫االســتثمار ثــاث ســنوات وقــد تضمــن الصــك املشــار إليــه (أنــه يف حالــة‬\n‫نــزع ملكيــة الوقــف مــن أي جهــة كانــت بعــد تعميــره أثنــاء مــدة التعاقــد‬\n‫فــإن التعويــض املقــدر ملنفعــة األرض يكــون للوقــف والتعويــض املقــدر‬\n\n                                                                                    ‫‪78‬‬\n\f     ‫للمبنــى يــوزع علــى عــدد ســنوات عقــد اإليجــار ويكــون للمعمــر قيمــة‬\n     ‫ســنوات مــا تبقــى لــه مــن العقــد الباقــي للوقــف ) ويطلــب احلكــم علــى‬\n     ‫الوقــف مبــا تبقــى لــه مــن قيمــة االســتثمار هكــذا ادعــى‪ ،‬أجــاب املدعى‬\n     ‫عليهمــا باملصادقــة علــى اســتثمار املدعــي الوقــف باملــدة املذكــورة وعلى‬\n     ‫إزالــة العقــار وأن املتبقــي للمدعــى عليه ثالث ســنوات من مدة االســتثمار‬\n     ‫وقــد عــوض الوقــف عــن قيمــة األنقــاض مببلــغ وقــدرة اثنــان وســتون‬\n     ‫مليونــا ومائــة وتســعة وخمســون ألف ـ ًا وتســعمائة وواحــد وأربعــون ريــال‬\n     ‫وخمســة وثالثــون هللــة وبعــد قســمته حســب الشــرط املذكــور يكــون‬\n     ‫للمدعــي مبلغــا وقــدره اثنــا عشــر مليونــا وأربعمائــة وواحــد وثالثــون‬\n     ‫ألف ـ ًا وتســعمائة وثمانيــة وثمانــون ريــال وســبع وعشــرون هللــة هكــذا‬\n     ‫أجابــا‪ ،‬بعرضــه علــى املدعــي قــال أطلــب احلكــم بتســليمي هــذا املبلــغ‪،‬‬\n     ‫جــرى االستفســار عــن صكــي النظــارة واالســتثمار فــوردت اإلجابــة‬\n     ‫بســريان مفعولهــا وعــدم الشــرح علــى ســجلها بشــيء‪ ،‬حيــث إن املدعــي‬\n     ‫واملدعــى عليهمــا قــد اتفقــا علــى قســمة التعويــض لألنقــاض يف حالــة‬\n     ‫نــزع العقــار قبــل إكمــال مــدة االســتثمار علــى عــدد الســنوات وأجيــز‬\n     ‫ذلــك مــن قبــل مصــدر الصــك ولقولــه تعالــى «يــا أيهــا الذيــن آمنــوا أوفــوا‬\n     ‫بالعقــود» ولقولــه صلــى اهلل عليــه وســلم «املســلمون علــى شــروطهم»‪،‬‬\n     ‫ملــا تقــدم صــدر احلكــم علــى ناظــري الوقــف بــأن يدفعــا للمدعــي املبلــغ‬\n     ‫املدعــى بــه ومقــداره اثنــا عشــر ميلون ـ ًا وأربعمائــة وواحــد وثالثــون ألف ـ ًا‬\n     ‫وتســعمائة وثمانيــة وثمانــون ريــال وســبع وعشــرون هللــة‪ ،‬قنــع املدعــي‬\n     ‫واملدعــى عليهمــا باحلكــم وبنــاء علــى املــادة التاســعة والســبعني بعد املائة‬\n     ‫مــن نظــام املرافعــات الشــرعية تقــرر رفــع هــذا اإلجــراء إلــى محكمــة‬\n     ‫االســتئناف لتدقيقــه‪ ،‬صــدق احلكــم مــن دائــرة األحــوال الشــخصية‬\n\n\n‫‪79‬‬\n\f              ‫الثانيــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا ‪......‬القاضي يف احملكمة العامة مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 34186030‬وتاريــخ ‪ 1434/04/22‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34993021‬وتاريــخ ‪ 1434/04/22‬ه ـ حضــر‬\n‫‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪......‬بصفتــه مالــك‬\n‫شــركة ‪ ......‬للتعميــر مبوجــب شــهادة تســجيل فــرع شــركة رقــم ‪......‬‬\n‫تاريــخ ‪1433/2/3‬ه ـ الصــادرة مــن وزارة التجــارة والصناعــة وحضــر‬\n‫حلضــوره ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪......‬و ‪......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...‬بصفتهمــا ناظريــن علــى‬\n‫وقــف ‪ ......‬مبوجــب صــك النظــارة الصــادر مــن هــذه احملكمــة برقــم‬\n‫‪ 17/13/8‬تاريــخ ‪1421/11/9‬ه ـ وبســؤال املدعــي عــن دعــواه قــال إننــي‬\n‫اســتثمرت عقــار الوقــف الواقــع يف ‪...‬مبوجــب الصــك الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 6/22/75‬تاريــخ ‪1417/9/17‬ه ـ واســتلمت العقــار‬\n‫بتاريــخ ‪1419/1/21‬ه ـ و ملــدة خمســة عشــر عــام وقــد أزيــل الوقــف‬\n‫بتاريــخ ‪1431/1/15‬ه ـ بعــد مضــي اثنــا عشــر عامــا وتبقــي لــي مــن مــدة‬\n‫االســتثمار ثــاث ســنوات وقــد تضمــن الصــك املشــار إليــه (أنــه يف حالــة‬\n‫نــزع ملكيــة الوقــف مــن أي جهــة كانــت بعــد تعميــره أثنــاء مــدة التعاقــد‬\n‫فــإن التعويــض املقــدر ملنفقــة األرض يكــون للوقــف والتعويــض املقــدر‬\n‫للمبنــى يــوزع علــى عــدد ســنوات عقــد اإليجــار ويكــون للمعمــر قيمــة‬\n‫ســنوات مــا مضــى لــه مــن العقــد الباقــي للوقــف ) أطلــب احلكــم علــى‬\n\n                                                                                    ‫‪80‬‬\n\f     ‫الوقــف مبــا تبقــى لــي مــن قيمــة االســتثمار وبعــرض ذلــك علــى املدعــى‬\n     ‫عليهمــا قــاال مــا ذكــره املدعــي مــن أنــه اســتثمر عقــار الوقــف الواقــع‬\n     ‫يف ‪ ...‬مبوجــب الصــك املشــار إليــه وأنــه بــدأ يف ‪1419/1/21‬ه ـ وأزيــل‬\n     ‫العقار بتاريخ ‪1431/1/15‬هـ وقد كانت مدة االســتثمار خمســة عشــر‬\n     ‫ســنة فهــذا كلــه صحيــح وقــد عــوض الوقــف عــن قيمــة االنقــاض مببلــغ‬\n     ‫وقــدرة اثنــان وســتون مليونــا ومائــة وتســعة وخمســون ألــف و تســعمائة‬\n     ‫وواحــد وأربعــون ريــال وخمســة وثالثــون هللــه (‪ 62,159,941,35‬ريــال)‬\n     ‫حســب التقديــر الصــادر مــن جلنــة الســاحات الشــمالية للعقــار رقــم‬\n     ‫‪ 11505‬بتاريخ ‪1434/1/26‬هـ وبعد قســمته حســب الشــرط املذكور‬\n     ‫يكــون للمدعــي مبلغــا ومقــداره اثنــا عشــر مليونــا وأربعمائــة وواحــد‬\n     ‫وثالثــون ألــف وتســعمائة وثمانيــة وثمانــون ريــال وســبعة وعشــرون هللــه‬\n     ‫(‪12.431.988.27‬ريــال) هكــذا أجابــا وبعرضــه علــى املدعــي قــال‬\n     ‫أطلــب احلكــم بتســليمي هــذا املبلــغ وعنــد وصــول القضيــة لهــذا احلــد‬\n     ‫رفعــت اجللســة لالستفســار عــن صكــي النظــارة واالســتثمار املشــار‬\n     ‫إليهمــا ويف جلســة أخــرى حضــر الطرفــان وقــد جــرى االستفســار عــن‬\n     ‫صــك النظــارة الصــادر مــن هــذه احملكمــة برقــم ‪ 17/13/8‬وتاريــخ‬\n     ‫‪1421/11/9‬ه ـ فعــاد بخطــاب مديــر الســجل املتضمــن أنــه ال يوجــد‬\n     ‫علــى ســجله أي شــرح يذكــر حتــى تاريــخ ‪1434/6/28‬ه ـ وســاري‬\n     ‫املفعــول كمــا جــرى االستفســار عــن صــك االســتثمار املشــار إليــه فعــاد‬\n     ‫بخطــاب مديــر الســجل ‪ 341551939‬تاريــخ ‪1434/6/26‬ه ـ املتضمــن‬\n     ‫أنــه ال توجــد علــى ســجله أي شــرح يذكــر حتــى تاريــخ ‪1434/6/28‬ه ـ‬\n     ‫وســاري املفعــول وباالطــاع عليــه وجدتــه يتضمــن إجــازة مصــدرة‬\n     ‫لالتفــاق علــى أن يقــوم « ‪ »......‬باســتثمار األرض الواقعــة ‪ ...‬واملعروفــة‬\n\n\n‫‪81‬‬\n\f‫‪...‬اململوكــة للوقــف مبوجــب الصــك الصــادر مــن احملكمــة برقــم ‪9/79‬‬\n‫يف ‪14238/3/1‬ه ـ ملــدة خمســة عشــر ســنة تبــدأ مــن تاريــخ تســليم املوقــع‬\n‫وأنــه يف حــال نــزع ملكيــة الوقــف مــن أي جهــة كانــت بعــد تعميــره‬\n‫أثنــاء مــدة التعاقــد فــإن التعويــض املقــدر ملنفعــة األرض يكــون للوقــف‬\n‫والتعويــض املقــدر للمبنــى يــوزع علــى عدد ســنوات عقــد اإليجار ويكون‬\n‫للمعمــر قيمــة ســنوات مــا بقــي لــه مــن العقــد و الباقــي للوقــف كمــا‬\n‫أحلــق بــه أن املســتثمر اســتلم املوقــع بتاريــخ ‪1419/1/21‬ه ـ كمــا جــرى‬\n‫اإلطــاع علــى صــورة تبليــغ عــن تقديــر عقــار صــادرة مــن جلنــة تطويــر‬\n‫الســاحات الشــمالية واملتضمنــة اســم املالــك وقــف ‪...‬رقــم الصــك ‪9/79‬‬\n‫وتاريخــه ‪1238/3/1‬ه ـ مبلــغ املبانــي (‪ 62,159,941,35‬ريــال) اثنــا‬\n‫وســتون ميلــون ومائــة وتســعة وخمســون ألــف وتســعمائة وواحــد وأربعــون‬\n‫ريــال وخمســة وثالثــون هللــة فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫ومــا جــرى اإلطــاع عليــه وحيــث أن املدعــي واملدعــى عليهمــا قــد اتفقــا‬\n‫علــى قســمة التعويــض لإلنقــاض يف حالــة نــزع العقــار قبــل إكمــال مــدة‬\n‫االســتثمار علــى عــدد الســنوات وأجيــز ذلــك مــن قبــل مصــدر الصــك‬\n‫ولقولــه تعالــى» يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود» ولقولــه صلــى اهلل‬\n‫عليــه وســلم «املســلمون علــى شــروطهم» وجلميــع مــا ذكــر بعاليــة فقــد‬\n‫حكمــت علــى ناظــري وقــف ‪......‬بــأن يدفعــا للمدعــي املبلــغ املدعــى بــه‬\n‫ومقــداره (‪12,431,988,27‬ريــال) اثنــا عشــر ميلــون وأربعمائــة وواحــد‬\n‫وثالثــون ألــف وتســعمائة وثمانيــة وثمانــون ريــال وســبعة وعشــرون هللــة‬\n‫وبعرضــه علــى الطرفــن قــرروا القناعــة بــه وبنــاء علــى مــا تضمنــه املــادة‬\n‫التاســعة والســبعون بعد املائة من نظام املرافعات الشــرعية فســيتم رفع‬\n‫هــذا اإلجــراء إلــى محكمــة االســتئناف لتدقيقــه وبــاهلل التوفيــق وصلــى‬\n\n\n                                                                                       ‫‪82‬‬\n\f     ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه وســلم حــرر يف ‪1434/8/30‬هـ‬\n     ‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n     ‫جــرى منــا نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف‬\n     ‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة‬\n     ‫مكــة املكرمــة االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪/‬‬\n     ‫‪......‬القاضــي باحملكمــة العامــة مبكــة املكرمــة برقــم ‪34311046‬‬\n     ‫وتاريخ‪1434/9/2‬ه ـ املتضمــن دعــوى ‪......‬ضــد ‪...... /‬وبدراســة الصــك‬\n     ‫وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم مــع مالحظــة التنبيــه‬\n     ‫املرفــق واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                                         ‫وســلم ‪.‬‬\n\n\n\n\n‫‪83‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":78,"source_page_end":83,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f47ab481045da258e0f60e641f2e977af941929169a4141247e0b8c745e7a328","normalized_text_hash":"44057e2aaace4dcf353eef69d72617d1f0caec13486133105329b030423e3ec5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p78-34311046"},{"id":"a9077a88-e0f8-5551-b0d0-a1c5ec570e2b","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -هبة -قطعة أرض -اإلفراغ الصوري -رد الشهادة ألنها جتر نفع ا لصاحبها -الصكوك الصادرة من كتابة العدل لها قوة اإلثبات -صرف النظر عن دعوى املدعي والية لعدم قيام البينة ومين املدعى عليها على نفي الدعوى .","document_number":"34146939","case_number":"32152179","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/18","year":"1434","subject":"عقار -هبة -قطعة أرض -اإلفراغ الصوري -رد الشهادة ألنها جتر نفع ا لصاحبها -الصكوك الصادرة من كتابة العدل لها قوة اإلثبات -صرف النظر عن دعوى املدعي والية لعدم قيام البينة ومين املدعى عليها على نفي الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34146939:‬تاريخه ‪1434/1/18:‬هـ‬\n                        ‫رقم الدعوى ‪32152179:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34166843‬تاريخه‪1434/3/21 :‬هـ‬\n\n\n      ‫عقــار‪ -‬هبــة ‪ -‬قطعــة أرض ‪ -‬اإلفــراغ الصــوري‪ -‬رد الشــهادة ألنهــا جتــر‬\n      ‫نفع ـ ًا لصاحبهــا‪ -‬الصكــوك الصــادرة مــن كتابــة العــدل لهــا قــوة‬\n      ‫اإلثبــات ‪ -‬صــرف النظــر عــن دعــوى املدعــي واليــة لعــدم قيــام البينــة‬\n                                     ‫وميــن املدعــى عليهــا علــى نفــي الدعــوى ‪.‬‬\n\n\n\n                                                    ‫محكمة ) ‪.‬‬\n                                                           ‫ّ‬      ‫‪ -1‬قاعدة ( العادة‬\n      ‫‪ -2‬مــا ذكــره أهــل العلــم مــن عــدم قبــول شــهادة الــزوج لزوجتــه والفــرع‬\n                                                                             ‫ألصلــه ‪.‬‬\n\n\n\n      ‫ا بأنــه يف عــام‬\n                      ‫ادعــى املدعــى بصفتــه ولي ـ ًا علــى والدتــه القاصــرة عق ـ ً‬\n      ‫‪1403‬ه ـ ســجلت والدتــه منــز ًال ( ذكــر موقعــه) بشــكل صــوري ألختــه‬\n      ‫املدعــى عليهــا لكــي حتصــل علــى القــرض العقــاري‪ -‬منــذ ذلــك الوقــت‬\n      ‫واملنــزل باســم املدعــى عليهــا ووالدتــه تســكن املنزل إلــى أن مت طردها‪-‬‬\n      ‫طلــب املدعــى واليــة احلكــم علــى املدعــى عليهــا بإفــراغ املنــزل لصالــح‬\n      ‫والدتــه‪ -‬أنكــرت املدعــى عليهــا ماجــا يف الدعــوى وذكــرت بــأن املنــزل‬\n      ‫ملــك لهــا وليــس لوالدتهــا‪ -‬احضــر املدعــى واليــة ســبعه شــهود‪ -‬جــرى رد‬\n      ‫شــهادة اخلمســة األول ألنهــا جتــر نفع ـ ًا لصاحبهــا‪ -‬وكذلــك رد شــهادة‬\n\n‫‪235‬‬\n\f‫الســادس والســابع ألنهــا غيــر موصلــه والتقــوى علــى معارضــه صــك‬\n‫التملــك‪ -‬جــرى االطــاع علــى صــك املنــزل وهــو باســم املدعــى عليهــا‬\n‫ومرهــون لصالــح صنــدوق التنميــة العقــاري‪ -‬جــرى إفهــام املدعــى واليــة‬\n‫بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه فطلــب ميينهــا‪ -‬حلفــت املدعى‬\n‫عليهــا اليمــن بعــد أن جــرى حتذيرهــا مــن مغبــة اليمــن الكاذبــة‪ -‬بنــاء‬\n‫علــى املــادة ‪ 80‬مــن نظــام القضــاء املتضمنــة بــأن الصكــوك الصــادرة‬\n‫مــن كتابــة العــدل حســب االختصــاص يكــون لهــا قــوة اإلثبــات ويجــب‬\n‫العمــل مبضمونهــا أمــام احملاكــم وال يجــوز الطعــن فيهــا إال تأسيس ـ ًا‬\n‫علــى مخالفتهــا ملقتضــى األصــول الشــرعية أو النظاميــة أو تزويرهــا‬\n‫وألن التأخــر يف إقامــة الدعــوى أكثــر مــن ثالثــن ســنه ممــا يضعــف‬\n‫الدعــوى ولــم جتــر العــادة بســكوت صاحــب احلــق عــن حقــه ملثــل هــذه‬\n‫املــدة والعــادة محكمــة وبنــاء علــى ميــن املدعــى عليهــا لــذا صــدر احلكم‬\n‫بصــرف النظــر عــن دعــوى املدعــى واليــة‪ -‬اعتــرض املدعــى واليــة علــى‬\n                       ‫احلكــم‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 32152179‬وتاريــخ‬\n‫‪ 1432/05/01‬ه ـ املقيــدة باحملكمــة برقــم ‪ 32475125‬وتاريــخ‬\n‫‪ 1432/05/01‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1432/06/21‬هـ أفتتحت‬\n‫اجللســة الســاعة ‪ 11 : 04‬وفيهــا حضــر ‪...‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬بخصــوص دعــواه ضــد ‪...‬ولــم حتضــر املدعيــة‬\n\n                                                                                      ‫‪236‬‬\n\f      ‫‪...‬والتــي مت إبالغهــا باخلطــاب املــؤرخ يف ‪1432/5/29‬ه ـ هــذا وإلبالغهــا‬\n      ‫مــرة أخــرى رفعــت اجللســة ويف جلســة اخــرى احلمــد هلل وحــده وبعــد ففــي‬\n      ‫يــوم الثالثــاء املوافــق ‪1432/09/02‬ه ـ أفتتحــت اجللســة الســاعة ‪01 : 19‬‬\n      ‫وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وادعــى‬\n      ‫علــى احلاضــرة معــه يف املجلــس الشــرعي ‪...‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪...‬قائــا يف دعــواه إنــه يف عــام ‪1403‬ه ـ ســجلت‬\n      ‫والدتــي ‪...‬املنــزل الواقــع بجبــل النــور مبكــة املكرمــة بإســم املدعــى‬\n      ‫عليهــا بشــكل صــوري لكــي حتصــل علــى القــرض العقــاري ومــن ذلــك‬\n      ‫الوقــت واملنــزل بإســم املدعــى عليهــا ووالدتــي تســكن املنــزل الــى أن مت‬\n      ‫طردهــا مــن املنــزل لــذا نطلــب احلكــم علــى املدعــى عليهــا بإفــراغ املنــزل‬\n      ‫املذكــور لصالــح والدتــي هكــذا ادعــى وبعــرض الدعوى علــى احلاضرة‬\n      ‫أجابــت قائلــة مــا ذكــره املدعــي غيــر صحيــح جملة وتفصيــا والصحيح‬\n      ‫أن هــذا املنــزل هــو ملكــي وليــس لوالدتــي وإذا كان لــدى املدعي البينة‬\n      ‫علــى مــا يذكــر فليحضرهــا هكــذا أجابــت بعــد ذلــك ســألت املدعــى‬\n      ‫عليهــا عــن صــك امللكيــة فقالــت إنــه ليــس لدي االن ومســتعدة إلحضاره‬\n      ‫يف اجللســة القادمة ولذا رفعت اجللســة ويف جلســة اخرى حضر الطرفان‬\n      ‫وســألت املدعــي هــل لديــه بينــة علــى دعــواه فأحضــر للشــهادة كال مــن‬\n      ‫‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وبســؤاله عــن عمــره‬\n      ‫وســكنه وصلــة قرابتــه بالطرفــن قــال عمــري ‪ 53‬عامــا وأســكن‬\n      ‫مبكــة وقرابتــي فاملدعــي واملدعــى عليهــا أخــوة لزوجتــي ثــم شــهد قائــا‬\n      ‫أشــهد هلل تعالــى بــأن والــدة زوجتــي ‪...‬أخبرتنــي بأنهــا قــد تلقــت األرض‬\n      ‫هبــة مــن والدهــا ‪...‬ولكنهــا طلبــت مــن والدهــا تســجيل األرض بإســم‬\n      ‫ابنتهــا املدعــى عليهــا ‪...‬كونهــا أرملــة يف ذلــك احلــن وتســتحق قــرض‬\n\n\n‫‪237‬‬\n\f‫صنــدوق التنميــة العقاريــة وأننــي أنــا مــن قمــت باالشــراف علــى بنــاء هــذه‬\n‫العمــارة وتســديد االقســاط بنــاء علــى تكليــف مــن عمتــي والــدة‬\n‫الطرفــن هــذا مــا لــدي وبــه أشــهد وبعــرض ذلــك علــى املدعيــة قالــت أمــا‬\n‫الشــاهد فــا أعلــم عــن حالــه شــيئا وأمــا شــهادته فغيــر صحيحــة هكــذا‬\n‫قــررت ثــم أحضــر ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪...‬وبســؤاله عــن عمــره وســكنه وصلــة قرابتــه بالطرفــن قــال عمــري ‪37‬‬\n‫عامــا وأســكن بجــدة وقرابتــي فاملدعــي واملدعــى عليــه أخــوة لوالدتــي‬\n‫وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد هلل تعالــى أننــي منــذ أن‬\n‫كنــت يف التاســعة مــن عمــري وأنــا أســمع أن ‪...‬هــي مــن تقــوم بســداد‬\n‫أقســاط صنــدوق التنميــة العقاريــة وقــد كان زوج خالتــي املدعــو ‪...‬هــو‬\n‫مــن يقــوم بســداد األقســاط يف الفتــرة األولــى ومــن ثم تولــى خالي املدعي‬\n‫الســداد لبقيــة األقســاط هــذا مــا لــدي وبــه أشــهد وبعــرض الشــاهد‬\n‫وشــهادته علــى املدعــى عليهــا قالــت أمــا الشــاهد فــا أعلــم عــن حالــه‬\n‫شــيئا وأمــا شــهادته فغيــر صحيحــة وبينــي وبــن هــذا الشــاهد خصومــة‬\n‫هكــذا قــررت كمــا أحضــر ‪...‬ســعودي اجلنســية مبوجب الســجل املدني‬\n‫رقــم ‪...‬وبســؤاله عــن عمــره وســكنه وصلــة قرابتــه بالطرفــن قــال‬\n‫عمــري ‪ 52‬عامــا وأســكن مبكــة وقرابتــي فاملدعــي واملدعــى عليهــا‬\n‫أخــوة لــي مــن الرضاعــة وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد هلل‬\n‫تعالــى بــأن جــدي ‪ ...‬قــد قــام بهبــة األرض مــورد النــزاع لوالــدة املدعــي‬\n‫واملدعــى عليهــا ‪...‬كمــا قــام بهبــة أراضــي جلميــع أبنــاءه هــذا مــا لــدي وبــه‬\n‫أشــهد وبعــرض الشــاهد وشــهادته علــى املدعــى عليهــا قــال أمــا الشــاهد‬\n‫فــا أعلــم عــن حالــه شــيئا وأمــا شــهادته فغيــر صحيحــة وبينــي وبينــه‬\n‫مشــاكل عائليــة هكــذا قــررت ثــم أحضــر ‪...‬ســعودي اجلنســية مبوجــب‬\n\n\n                                                                                          ‫‪238‬‬\n\f      ‫الســجل املدنــي رقــم ‪...‬وبســؤاله عــن عمــره وســكنه وصلــة قرابتــه‬\n      ‫بالطرفــن قــال عمــري ‪ 29‬عامــا وأســكن مبكــة وقرابتــي فاملدعــي‬\n      ‫واملدعــى عليــه أخــوة لوالدتــي وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد‬\n      ‫هلل تعالــى بأنــه منــذ أن كنــت يف الثامنــة مــن عمــري وأنــا أســمع بــأن‬\n      ‫العمــارة جلدتــي ‪...‬وقــد قامــت جدتــي بإعطائنــا شــقة وغرفــة للســكن‬\n      ‫فيهــا ألنهــا مالكــة العمــارة هــذا مــا لــدي وبــه أشــهد وبعــرض الشــاهد‬\n      ‫وشــهادته علــى املدعــى عليهــا قالــت أمــا الشــاهد فــا أعلــم عــن حالــه‬\n      ‫شــيئا وأمــا شــهادته فغيــر صحيحــة حيــث إنــه صاحــب مصلحــة يف البنــاء‬\n      ‫يف العمــارة هكــذا قــررت ثــم أحضــر ‪...‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪...‬وبســؤالها عــن عمرهــا وســكنها وصلــة قرابتهــا‬\n      ‫بالطرفــن قالــت عمــري ‪ 57‬عامــا وأســكن بجــدة وقرابتــي فاملدعــي‬\n      ‫واملدعــى عليهــا أخــوة أشــقاء وبســؤالها عمــا لديهــا مــن شــهادة قالــت‬\n      ‫أشــهد هلل تعالــى أن االرض والعمــارة مــورد النــزاع ملــك لوالدتــي ‪...‬‬\n      ‫وتلقتهــا هبــة مــن والدهــا ولكنهــا طلبــت مــن خالــي ‪...‬كتابــة االرض‬\n      ‫بإســم املدعــى عليهــا لكونهــا أرملــة وتســتحق قــرض صنــدوق التنميــة‬\n      ‫العقاريــة هــذا مــا لــدي وبــه أشــهد وبعــرض الشــاهدة وشــهادتها علــى‬\n      ‫املدعــى عليهــا قالــت أمــا الشــاهدة فــا أعلــم عــن حالهــا شــيئا وأمــا‬\n      ‫شــهادتها فغيــر صحيحــة وبينــي وبينهــا خصومــة هكــذا قــررت ثــم‬\n      ‫أحضــر ‪...‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وبســؤالها عــن‬\n      ‫عمرهــا وســكنها وصلــة قرابتهــا بالطرفــن قالــت عمــري ‪ 72‬عامــا‬\n      ‫وأســكن مبكــة وقرابتــي فاملدعــي واملدعــى عليــه أبنــاء أخي وبســؤالها‬\n      ‫عمــا لديهــا مــن شــهادة قالــت أشــهد هلل تعالــى بــأن ‪ ...‬قــد تلقــت االرض‬\n      ‫مــورد النــزاع هبــه مــن والدهــا وقــد قام شــقيقي ‪...‬بتســجيل االرض بإســم‬\n\n\n‫‪239‬‬\n\f‫املدعــى عليهــا لكونهــا أرملــة وتســتحق القــرض مــن صنــدوق التنميــة‬\n‫العقاريــة وكانــت والــدة املدعــى عليهــا هــي مــن تقــوم بســداد االقســاط‬\n‫وتكلــف بذلــك زوج ابنتهــا ‪...‬وابنهــا ‪...‬هــذا مــا لــدي مــن شــهادة وبعــرض‬\n‫الشــاهدة وشــهادتها علــى املدعــى عليــه قالــت أمــا الشــاهدة فــا أعلــم‬\n‫عــن حالهــا شــيئا وأمــا شــهادتها فغيــر صحيحــة ثــم أحضــر ‪ ...‬ســعودية‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وبســؤالها عــن عمرها وســكنها‬\n‫وصلــة قرابتهــا بالطرفــن قالــت عمــري ‪ 47‬عامــا وأســكن مبكــة‬\n‫وقرابتــي فاملدعــي واملدعــى عليهــا أخــوة أشــقاء وبســؤالها عمــا لديهــا‬\n‫مــن شــهادة قالــت أشــهد هلل تعالــى بــأن والدتــي قــد تلقــت االرض مــورد‬\n‫النــزاع هبــه عــن طريــق والدهــا وكان عمــري يف ذلــك احلــن عشــرون‬\n‫ســنة وقــد طلبــت والــدت مــن خالــي ‪...‬تســجيل العقــار بإســم املدعــى‬\n‫عليهــا كونهــا مطلقــة وتســتحق قــرض صنــدوق التنميــة العقاريــة‬\n‫وكانــت والدتــي هــي مــن تقــوم بســداد االقســاط وتكلــف بذلــك زوج‬\n‫ابنتهــا ‪ ...‬وابنهــا ‪...‬هــذا مــا لــدي وبــه أشــهد وبعــرض الشــاهدة وشــهادتها‬\n‫علــى املدعــى عليهــا قالــت أمــا الشــاهدة فــا أعلــم عــن حالهــا شــيئا وأمــا‬\n‫شــهادتها فغيــر صحيحــة وتوجــد بينــي وبينهــا خصومــة هكــذا قــررت‬\n‫هــذا وحلــن وروود صــك العقــار مــن كتابــة عــدل مكــة رفعــت اجللســة‬\n‫ويف جلســة اخــرى حضــر الطرفــان وحيــث انــه قــد ســقط ســهوا ســؤال‬\n‫املدعــى عليهــا عمــا اســتمهلت مــن إحضارهــا لصــك امللكيــه يف اجللســه‬\n‫الســابقه فقــد جــرى ســؤالها عنــه فقالــت انــه مفقــود مــن شــهر جمــاد‬\n‫االولــى مــن عــام ‪1432‬ه ـ وأبــرزت صــورة مــن صحيفــة النــدوه بتاريــخ‬\n‫‪1432/5/24‬ه ـ العــدد ‪ 15948‬واملتضمــن اعــان وكيــل املدعــي عليهــا‬\n‫عــن فقــدان الصــك كمــا ابــرزت صــورة مــن الصــك رقــم ‪ 368‬يف‬\n\n\n                                                                                       ‫‪240‬‬\n\f      ‫‪1403/5/18‬ه ـ وباالطــاع عليهــا وجــد يتضمــن ‪...‬قطعــة االرض ‪313‬‬\n      ‫الواقعــه مبكــه املكرمــة شــمال شــرق ‪ ...‬للمدعــى عليهــا ‪...‬هــذا وقــد‬\n      ‫جــرت الكتابــة لكتابــة عــدل االولــى مبكــه املكرمــه باخلطــاب رقــم‬\n      ‫‪ 32/1182400‬يف ‪1432/9/15‬ه ـ بخصــوص بعــث اصــل صــك العقــار‬\n      ‫ولــم يردنــي اجلــواب حتــى تاريخــه هــذا وحلــن ورود اجلــواب رفعــت اجللســه‬\n      ‫ويف جلســة اخــرى ويف جلســة اخــرى حضــر الطرفــان وكان قــد وردنــي‬\n      ‫خطــاب كتابــة عــدل األولــى مبكــه املكرمــة رقــم ‪ 332005971‬يف‬\n      ‫‪1433/12/22‬ه ـ بخصــوص بعــث صــورة خطيــة مــن مــن ســجل الصــك‬\n      ‫رقــم ‪ 368‬يف ‪1433/5/17‬ه ـ علمــا ان الصــك مرهــون لــدى صنــدوق‬\n      ‫التنميــة العقــاري وباإلطــاع علــى الصــك املذكــور اعــاه وجــد بــه (‬\n      ‫حضــور ‪ ...‬قائــا أن مــن اجلــاري يف ملكــي قطعــة األرض رقــم ‪313‬‬\n      ‫الواقعــة مبكــه املكرمــة شــمال شــرق ‪ ...‬واملفــرزه مــن مخطــط ‪ ...‬انــي‬\n      ‫االن وهبــت قطعــة األرض املذكــورة أعــاه إلــى ‪...‬واملنتهــي برهــن‬\n      ‫كامــل احملــدود بباطنــه لصنــدوق التنميــة العقــاري ) ‪.‬بســؤال املدعــي‬\n      ‫هــل لديــه زيــادة بينــة قــال ليــس لــدي ســوى مــا قدمــت واطلــب البــت يف‬\n      ‫القضيــة وعليــه وللتأمــل وانتهــاء وقــت اجللســه رفعــت اجللســه ويف جلســة‬\n      ‫اخــرى حضــر الطرفــان وبعــد الدراســة والتأمــل يف ضبــوط اجللســات‬\n      ‫وجــد أنــه يتــم ضبــط مضمــون صــك الواليــة وســؤال املدعــي واليــة أبــرز‬\n      ‫الصــك رقــم ‪1432/6/15 3213414‬ه ـ الصــادر مــن احملكمــة العامــة‬\n      ‫بجــدة املتضمــن اقامــة ‪...‬ولــي علــى والدتــه ‪ ...‬وباإلطــاع علــى شــهادة‬\n      ‫الشــهود والذيــن أحضرهــم املدعــي واليــة وجــدت شــهادة الشــاهد ‪...‬‬\n      ‫تلحقــه التهمــه كونــه يجــر نفعــا بشــهادة لزوجتــه وكذلــك احلــال‬\n      ‫بالنســبة لشــهادة كل مــن ‪...‬و‪...‬فهــم بذلــك يجــرون نفعا ألنفســهم وكذا‬\n\n\n‫‪241‬‬\n\f‫احلــال شــهادة كل م ‪...‬و‪...‬فهــم بذلــك يجــرون ألنفســهم نفعــا عــن طريــق‬\n‫أمهاتهــم وقــد قــرر اهــل العلــم عــدم قبول شــهادة الزوج لزوجتــه و لوالدته‬\n‫أمــا مــا يتعلــق بشــهادة الشــاهد ‪...‬وشــهادة الشــاهد ‪...‬فهــى غيــر موصلــة‬\n‫إلــى ســبق متلــك والــدة املدعــي واليــة ‪...‬وقبضهــا للهبــة مــورد النــزاع مــن‬\n‫والدهــا وبالتالــي فهــي ال تقــوى علــى معارضــة صــك اإلفــراغ املذكــور‬\n‫مضمونــه اعــاه وبســؤال املدعــي واليــة هــل يرغــب يف حتليــف املدعــى‬\n‫عليهــا اليمــن علــى نفــي دعــواه اجــاب بأنــه يطلبهــا ويطلــب حتليفهــا‬\n‫كذلــك علــى نفــي حصــول املفاوضــة يف مــا بــن املدعــى عليهــا ووالدتهــا‬\n‫علــى اإلفــراغ مقابــل مبلــغ مالــي لتســجيلها األرض بصنــدوق التنميــة‬\n‫العقــاري وبعــرض ذلــك علــى املدعــى عليهــا اســتعدت بإدائهــا وبعــد‬\n‫حتذيرهــا مــن مغبــة اليمــن الكاذبــة حلفــت قائلــة بعــد طلبــي منهــا (‬\n‫واهلل العظيــم الــذي ال إلــه إال هــو الرحمــن الرحيــم عالم الغيب والشــهادة‬\n‫الطالــب الغالــب الضــار النافــع الــذي يعلــم خائنــة األعــن ومــا تخفــي‬\n‫الصــدور أنــي قــد تلقيــت األرض الواقعــة مبكــه املكرمــة ‪ ...‬مــن قبــل‬\n‫جــدي ‪...‬هبــة صحيحــة وليــس لوالدتــي حــق فيهــا ولــم تســجل األرض‬\n‫مــورد النــزاع لــي مــن قبــل جــدي هبــة صوريــة ألجــل احلصــول علــى قــرض‬\n‫مــن صنــدوق التنميــة العقــاري ولــم اتفــاوض مــع والدتــي علــى افــراغ‬\n‫األرض مــورد النــزاع واعادتهــا مللكيتهــا مقابــل مبلــغ مــن املــال وذلــك‬\n‫عــوض عــن تســجيل األرض بأســمي لــدى صنــدوق التنميــة العقــاري واهلل‬\n‫العظيــم واهلل العظيــم واهلل العظيــم ) هكــذا حلفــت وعليــه فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء علــى الصــك الصــادر مــن كتابــة‬\n‫عــدل االولــى مبكــه املكرمــة رقــم ‪ 368‬يف ‪1403/5/18‬ه ـ واملتضمــن‬\n‫هبــة ‪...‬قطعــة االرض ‪ 313‬الواقعــه مبكــه املكرمــة شــمال شــرق جبــل‬\n\n\n                                                                                       ‫‪242‬‬\n\f      ‫النــور للمدعــى عليهــا ‪...‬فهــي قــد انتقلــت للمدعــى عليهــا عــن طريــق‬\n      ‫الهبــة وهــذا يعنــي متلكهــا لهــا حيــث إن األوراق الصــادرة مــن كتــاب‬\n      ‫العــدل حســب االختصــاص يكــون لهــا قــوة األثبــات ويجــب العمــل‬\n      ‫مبضمونهــا امــام احملاكــم وال يجــوز الطعــن فيهــا اال تأسيســا علــى‬\n      ‫مخالفتهــا ملقتضــى األصــول الشــرعية او النظاميــة او تزويرهــا كمــا‬\n      ‫نصــت علــى ذلــك املــادة الثمانــون مــن نظــام القضــاء وكذلــك فــإن تأخــر‬\n      ‫أقامــة الدعــوى ألكثــر مــن ثالثــن ســنة ممــا يضعــف الدعــوى ولــم جتــر‬\n      ‫العــادة بســكوت صاحــب احلــق عــن حقــه ملثــل هــذه املــدة والعــادة‬\n      ‫محكمــة وبنــاء علــى اليمــن التــي حلفتهــا املدعــى عليهــا بنــاء لطلــب‬\n      ‫املدعــي واليــة فقــد افهمــت املدعــي واليــة بأنــه لــم يثبــت لــدي ســبق متلــك‬\n      ‫والدتــه للهبــة مــورد النــزاع وافهمتــه بانــه ال حــق لوالدتــه يف األرض مــورد‬\n      ‫النــزاع وصرفــت النظــر عــن دعــواه وبذلــك حكمــت وبعرضــه علــى‬\n      ‫الطرفــن قنعــت بــه املدعــى عليهــا وقــرر املدعــي واليــة عــدم قناعتــه‬\n      ‫باحلكــم وطلــب رفعــه حملكمــة االســتئناف فاجيــب لطلبــه وجــرى‬\n      ‫تســليمه صــورة مــن صــك احلكــم لالعتــراض عليــه خــال الفتــرة‬\n      ‫النظاميــه ثالثــون يومـ ًا وافهــم اذا لــم يتقــدم خاللهــا باعتراضــه فســوف‬\n      ‫يســقط حقــه يف طلــب االســتئناف ويكتســب احلكــم القطعيــة ففهــم‬\n      ‫ذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                    ‫وسلم ‪ .‬حرر يف ‪ 1434/01/18‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد يف يــوم اإلثنــن املوافــق‪ 1434/05/20‬ه ـ افتتحــت‬\n      ‫اجللســة حيــث عــادت املعاملــة مــن محكمــة االســتئناف باخلطــاب رقــم‬\n      ‫‪ 34642910‬يف ‪1434/3/28‬هـ مصادقا عليها بالقرار رقم‪34166843‬‬\n      ‫يف ‪1434/3/21‬ه ـ ونصــه بعــد املقدمــة ( وبدراســة الصــك وصــورة‬\n\n\n‫‪243‬‬\n\f‫ضبطــه والئحتــه االعتراضيــة تقــرر باالكثريــة املوافقــة علــى احلكــم‬\n‫قاضــي اســتئناف ‪...‬قاضــي اســتئناف ‪...‬لــه وجهــة نظــر رئيــس الدائــرة ‪...‬‬\n‫ختمــه وتوقيعــة ) ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                           ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/20‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبحافظــة جــدة برقــم ‪ 32/475125‬وتاريــخ‬\n‫‪1434/3/10‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n‫‪...‬القاضــي باحملكمــة العامــة مبحافظــة جــدة برقــم ‪ 3414639‬وتاريــخ‬\n‫‪1434/1/18‬ه ـ ‪ ،‬املتضمــن دعــوى ‪...‬ضــد ‪ ،...‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والئحتــه اإلعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم‪.‬‬\n‫واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                          ‫وســلم‪.‬‬\n\n\n\n\n                                                                                    ‫‪244‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":235,"source_page_end":244,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"564ad6999aeaaa161367e27cb104e7686fb57e23e9fe1a05793a3cc3127882bc","normalized_text_hash":"bda7b32b1eb069534e3f4e54b2f6b26418ac520a6c37bb7fba4dc1ee1c2c4936","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p235-34146939"},{"id":"9c653682-4584-5157-a4b0-46116db3c575","document_type":"judgment","category":"judicial","subcategory":"general","title":"هبة -مطالبة بإثبات هبة متوفى -إقرار بعض املدعى عليهم وإنكار البعض -إثبات املدعي صحة دعواه بالبينة -التحوط يف حقوق القصر -شاهدان معدالن ومين االستظهار -احلكم بصحة دعوى املدعى -وجوب رفع الدعوى إلى محكمة الاستئناف عند","document_number":"34189207","case_number":"3420212","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/16","year":"1434","subject":"هبة -مطالبة بإثبات هبة متوفى -إقرار بعض املدعى عليهم وإنكار البعض -إثبات املدعي صحة دعواه بالبينة -التحوط يف حقوق القصر -شاهدان معدالن ومين االستظهار -احلكم بصحة دعوى املدعى -وجوب رفع الدعوى إلى محكمة الاستئناف عند","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34189207 :‬تاريخه ‪1434/4/16 :‬هـ‬\n                           ‫رقم الدعوى ‪3420212 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‬\n                 ‫‪ 34204826:‬تاريخه ‪1434/5/4 :‬هـ‬\n\n\n       ‫هبــة ‪ -‬مطالبــة بإثبــات هبــة متوفــى ‪ -‬إقــرار بعــض املدعــى عليهــم‬\n       ‫وإنــكار البعــض ‪ -‬إثبــات املدعــي صحــة دعــواه بالبينــة ‪ -‬التحــوط يف‬\n       ‫حقــوق القصــر ‪ -‬شــاهدان معــدالن وميــن االســتظهار ‪ -‬احلكــم بصحــة‬\n       ‫دعــوى املدعــى‪ -‬وجــوب رفــع الدعــوى إلــى محكمــة االســتئناف عنــد‬\n                                                                  ‫وجــود قصــر ‪.‬‬\n\n\n\n       ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                           ‫حكمه‪.‬‬\n\n\n\n\n       ‫أقــام املدعــى دعــوى علــى ورثــة متوفــى يطالــب بإثبــات هبــة مورثهــم‬\n       ‫كامــل نصيبــه املشــاع مــن إرثــه مــن والدتــه يف عقــار أقيــم عليــه بيــت‬\n       ‫وذكــر أنــه قبضــه واســتلمه منــه يف حياتــه وأنــه تــويف قبــل أن يفــرغ الهبــة‬\n       ‫للمدعــي وطلــب إثبــات ذلــك والتهميــش مبوجبــه علــى صــك امللكيــة ‪-‬‬\n       ‫أنكــر بعــض املدعــى عليهــم علمهــم مبــا يطالــب بــه املدعــي وأقــروا بــأن‬\n       ‫ال مانــع لديهــم إذا ثبتــت دعــوى املدعــى مــن احلكــم لــه مبــا يدعيــه وأقــر‬\n       ‫بعــض املدعــى عليهــم بصحــة مــا جــاء يف الدعــوى ‪ -‬طلبــت احملكمــة‬\n       ‫مــن املدعــي البينــة فأحضــر شــاهدين معدلــن شــهدا بصحــة دعــوى‬\n\n‫‪245‬‬\n\f‫املدعــى كمــا طلبــت احملكمــة مــن املدعــى ميــن االســتظهار احتياطــا‬\n‫حلــق القصــار مــن الورثــة فحلــف املدعــي ‪ -‬ثبــت لــدى احملكمــة أن مــورث‬\n‫املدعــى عليهــم قــد وهــب املدعــي كامــل نصيبــه مــن إرثــه مــن أمــه مــن‬\n‫العقــار املذكــور وحكمــت بذلــك وقــررت رفــع هــذا اإلجــراء حملكمــة‬\n‫االســتئناف لوجــود القاصــر‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )000‬رئيــس احملكمــة العامــة بعنيــزة‬\n‫وبنــاء علــى الدعــوى املقدمــة ضــد ورثة (‪ )000‬بشــأن إثبــات هبة واحملالة‬\n‫لنــا برقــم ‪ 3420212‬وتاريــخ ‪1434/1/12‬ه ـ املقيــدة باحملكمــة وتاريــخ‬\n‫‪1434/1/12‬ه ـ ففــي يــوم االثنــن املوافــق ‪1434/4/15‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 9 : 00‬عليه حضر (‪ )000‬ســعودي اجلنســية فادعى ضد‬\n‫احلاضريــن معــه يف مجلــس احلكــم كال مــن وكيــا عــن بالوكالــة‬\n‫ســجل رقــم ‪ 9544‬يف ‪2010/10/11‬م الصــادرة مــن كتابــة العــدل‬\n‫الســورية يف‪ 500‬املصــادق عليهــا مــن اجلهــات املختصــة وحضــر (‪)000‬‬\n‫ســعودي اجلنســية الوكيــل الشــرعي عــن (‪ )000‬املذكــورة بصفتهــا ولية‬\n‫علــى ابنتهــا القاصــرة (‪ )000‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل بســوريا برقــم ‪ 184‬املوافــق ‪ 28‬نيســان ‪2009‬م املصــادق عليهــا‬\n‫مــن اجلهــات املختصــة واحلاضــرة (‪ )000‬أصيلــة عــن نفســها ووكيلــة عــن‬\n‫كل مــن بالوكالــة رقــم يف ‪1431/3/13‬ه الصــادرة مــن كتابــة عــدل‬\n‫‪ ......‬واملدعــى عليهــم هــم جميــع ورثــة (‪ )000‬مبوجــب صــك حصــر الورثــة‬\n‫الصــادر مــن هــذه احملكمــة برقــم يف ‪1427/9/9‬ه ـ املتضمــن وفــاة‬\n‫(‪ )000‬انحصــار إرثــه يف زوجتيــه ويف بناتــه وجميعهــم بالغــون ماعــدا‬\n\n                                                                                  ‫‪246‬‬\n\f      ‫(‪ )000‬املولــودة يف ‪1424/2/29‬ه ـ ويف العاصــب أخيه الشــقيق قائال يف‬\n      ‫دعــواه ‪ :‬توفيــت والدتــي عــام ‪1412‬هـ وانحصر إرثها يف ولديها وشــقيقي‬\n      ‫(‪ )000‬مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم‬\n      ‫‪ 2/18‬يف ‪1413/2/27‬ه ـ وخلفــت مــن ضمــن تركتهــا منزلهــا الواقــع‬\n      ‫يف مدينــة (‪ )000‬اململــوك لوالدتــي الصــك الصــادر مــن هــذه احملكمــة‬\n      ‫برقــم ‪ 1/140‬يف ‪1402/3/25‬ه ـ حــدوده وأطوالــه مــا يلــي شــماال ‪:‬‬\n      ‫القطعــة رقــم ‪ 300‬بطــول أربعــة وعشــرين متــرا وجنوبــا‪ :‬القطعــة رقــم‬\n      ‫‪ 296‬بطــول أربعــة وعشــرين متــرا وشــرقا ‪:‬شــارع عــرض عشــرة أمتــار‬\n      ‫بطــول اثنــن وعشــرين متــرا وغربــا ‪:‬القطعــة رقــم ‪ 299‬بطــول اثنــن‬\n      ‫وعشــرين متــرا واملســاحة اإلجماليــة خمســمائة وثمانيــة وعشــرين متــرا‬\n      ‫مربعــا وإن أخــي مــورث املدعــى عليهــم وهبنــي يف حياتــه كامــل نصيبــه‬\n      ‫املشــاع مــن إرثــه مــن والدتــه مــن هــذا البيــت وقــد قبضتــه واســتلمت منــه‬\n      ‫يف حياتــه ثــم تــويف يرحمــه اهلل بتاريــخ ‪1427/7/12‬ه ـ قبــل أن يفــرغ‬\n      ‫لــي نصيبــه أطلــب إثبــات ذلــك والتهميــش مبوجبــه علــى صــك ملكيــة‬\n      ‫هــذا البيــت هــذه دعــواي هكــذا ادعــى املدعــي‪ ،‬وبعــرض الدعــوى علــى‬\n      ‫املدعــى عليهــم أجــاب بقولهمــا ال نعلــم عمــا جــاء يف دعــوى املدعــي واذا‬\n      ‫اثبــت دعــواه فليــس لــدى موكلينــا مانــع مــن احلكــم لــه مبــا تضمنتــه‬\n      ‫دعــواه واجابــت (‪ )000‬باألصالــة والوكالــة بقولهــا‪ :‬مــا ذكــره املدعــي‬\n      ‫يف دعــواه فكلــه صحيــح فــإن مورثنــا يرحمــه اهلل قد وهــب عمنا املدعي‬\n      ‫كامــل نصيبــه املشــاع يف حياتــه مــن إرثــه مــن والدتــه مــن هــذه البيــت‬\n      ‫املذكــور يف الدعــوى وقبــض الهبــة يف حيــاة مورثنــا ولكــن مورثنــا‬\n      ‫تــويف ولــم يفــرغ لــه وال مانــع لدينــا ولــدى موكلينــا مــن إفــراغ نصيــب‬\n      ‫مورثنــا مــن هــذه األرض للمدعــي هكــذا أجابــت‪ ..‬وطلبــت مــن املدعــي‬\n\n\n‫‪247‬‬\n\f‫البينــة فأحضــر كال مــن (‪ )000‬ســعودي اجلنســية وهومــن مواليــد عــام‬\n‫‪1392‬ه ـ ومــن ســكان (‪ )000‬وال تربطــه عالقــة بالطرفــن ســوى ان‬\n‫املدعــي زوج والدتــه و(‪ )000‬ســعودي وهــو مــن مواليــد عــام ‪1381‬ه ـ ومن‬\n‫ســكان (‪ )000‬وال تربطــه عالقــة بالطرفــن ســوى ان املدعــي زوج اختي‬\n‫ولــدى ســؤالهما عــن مــا لديهمــا مــن شــهادة شــهد كل واحــد منهمــا‬\n‫مبفــرده قائــا ‪ :‬أشــهد بــاهلل تعالــى بــأن مــورث املدعــى عليهــم قــد وهــب‬\n‫شــقيقه املدعــي هــذا احلاضــر كامــل نصيبــه مــن البيــت املذكــورة‬\n‫حدودهــا وأطوالهــا يف دعــوى املدعــي أعــاه الواقــع بحــي (‪ )000‬مــن‬\n‫مدينــة بــدون مقابــل وأن املدعــي قــد قبــض هــذه الهبــة وأســتلمها يف حيــاة‬\n‫مــورث املدعــى عليهــم وهــو يف حالــة صحــة مــن عقلــه هــذا مــا لــدي و بــه‬\n‫أشــهد هكــذا شــهد كل واحــد مــن الشــاهدين وبعــرض الشــاهدين‬\n‫وشــهادتهما علــى املدعــى عليهــم قــال مــا نقــول يف الشــهادة والشــهود اال‬\n‫خيــرا وقالــت (‪ :)....‬مــا ذكــره الشــاهدان فكلــه صحيــح هكــذا قــرروا‬\n‫فطلبــت معدلــن للشــاهدين فأحضــر املدعــي كال مــن (‪ )000‬ســعودي‬\n‫اجلنســية مبوجب الهوية الوطنية رقم (‪ )000‬و(‪ )000‬وشــهد كل واحد‬\n‫منهمــا بقولــه ‪ :‬أشــهد هلل تعالــى بعدالــة الشــاهدين املذكوريــن أعــاه‬\n‫واســتقامتهما يف الديــن واملــروءة هكــذا شــهدا‪ ،‬كمــا جــرى التأكــد‬\n‫مــن مطابقــة الصــك لســجله وأنــه لــم يطــرأ عليــه شــيء حســب خطــاب‬\n‫رئيــس كتابــة عــدل عنيــزة يف ‪1434/2/5‬ه ـ وهو صالــح لإلفراغ ونظرا‬\n‫ألن مــن ضمــن الورثــة قاصــرة وألن ميــن االســتظهار تشــرع احتياطــا حلــق‬\n‫القصــار لــذا طلبــت مــن املدعــي أن يحلــف ميــن االســتظهار فحلــف بعــد‬\n‫أن خوفتــه بــاهلل مــن مغبــة اليمــن الكاذبــة قائــا ‪ :‬واهلل العظيــم الــذي‬\n‫ال الــه إال هــو إن أخــي الشــقيق (‪ )000‬مــورث املدعــى عليهــم قــد وهبنــي‬\n\n\n                                                                                    ‫‪248‬‬\n\f      ‫نصيبــه مــن العقــار الــذي ادعــي بــه املذكــورة حــدوده وأطوالــه أعــاه‬\n      ‫العائــدة لنــا بــاإلرث مــن مورثتنــا وإننــي قــد قبضــت هــذه الهبــة منــه يف‬\n      ‫حياتــه رحمــه اهلل ‪ ،‬هكــذا حلــف كمــا جــرى اإلطــاع علــى صــك‬\n      ‫حصــر ورثــة الصــادر مــن هــذه احملكمــة ‪ 25/18‬يف ‪1413/2/27‬ه ـ‬\n      ‫املتضمــن وفاتهــا يف ‪1412/2/24‬ه ـ وانحصــار إرثهــا يف ولديهــا وهــم‬\n      ‫وجميعهــم بالغــون ودراســة كافــة أوراق املعاملــة ومنهــا صــك ملكيــة‬\n      ‫العقــار املتضمــن متلــك للعقــار وصــك حصــر ورثــة خلــف املذكــور وألن‬\n      ‫وكاالت املدعــى عليهــم تخــول لهــم حــق املطالبــة واملدافعــة والــرد علــى‬\n      ‫الدعــوى وألن املدعــي اثبــت بالبينــة املعتبــرة شــرعا صحــة دعــواه وحلــف‬\n      ‫ميــن االســتظهار علــى صحــة دعــواه فقــد ثبــت لــدي أن مــورث املدعــى‬\n      ‫عليــه مقــد وهــب شــقيقه املدعــي كامــل نصيبــه مــن إرثــه مــن امــه‬\n      ‫(‪ )000‬مــن هــذا العقــار املذكــور بــدون مقابــل ومبوجبــه فقــد انتقــل‬\n      ‫نصيبــه املشــاع مــن هــذا العقــار ألخيــه املدعــي وبذلــك حكمــت وقــررت‬\n      ‫التهميــش مبوجبــه بذلــك علــى صــك امللكيــة وســجله بعــد تصديــق‬\n      ‫احلكــم مــن محكمــة االســتئناف ‪ ،‬وبعــرض احلكــم علــى املدعــى‬\n      ‫عليهــم وكالــة قنعــوا بــه وألن مــن ضمــن الورثــة قاصــرة لــذا قــررت رفــع‬\n      ‫هــذا اإلجــراء حملكمــة االســتئناف لتدقيقــه حســب املتبــع وصلــى اهلل‬\n                                       ‫علــى نبينــا محمــد حــرر يف ‪1434/4/15‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )000‬رئيــس احملكمــة العامــة بعنيــزة‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنا من فضيلــة رئيس احملكمة العامة بعنيزة‬\n      ‫برقــم وتاريــخ ‪1434/01/12‬ه ـ املقيــدة باحملكمــة برقــم ‪3496134‬‬\n      ‫وتاريــخ ‪1434/01/12‬ه ـ ففــي يــوم الســبت املوافــق ‪1434/05/18‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة احلاديــة عشــر وقــد وردتنا املعاملــة من محكمة‬\n\n\n‫‪249‬‬\n\f‫االســتئناف بالقصيــم برقــم يف ‪1434/5/7‬ه ـ وقــد ظهــر علــى الصــك‬\n‫مــن اصحــاب الفضيلــة قضــاة الدائــرة احلقوقيــة الثانيــة كل مــن(‪)000‬‬\n‫و(‪)000‬و(‪ )000‬مبــا مضمونــه (احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى‬\n‫هــذا الصــك رقــم ‪ 34189207‬يف ‪1434/4/16‬ه ـ الصــادر مــن فضيلــة‬\n‫الشــيخ(‪ )000‬واصدرنــا القــرار رقــم ‪ 34204826‬وتاريــخ ‪1434/5/4‬ه ـ‬\n‫املتضمــن التصديــق علــى احلكــم الصــادر مبوضــوع هــذه الدعــوى ‪.‬‬\n‫قاضــي اســتئناف (‪ )000‬قاضــي اســتئناف(‪ )000‬رئيــس الدائــرة (‪)000‬‬\n‫ختمهــم وتوقيعهــم انتهــى )) بــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/18‬هــ‪.‬‬\n‫احلمــدهلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n‫الثانيــة مبحكمــة االســتئناف مبنطقــة القصيــم علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة وتاريــخ ‪1434/4/24‬هــ؛ اخلاصــة‬\n‫بدعــوى (‪ )000‬ضــد ورثــة (‪)000‬؛ بشــأن إثبــات هبــة مورثهــم نصيبــه‬\n‫مــن املنــزل الواقــع العائــد لهمــا بــاإلرث مــن أمهمــا ؛ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيلتــه وتاريــخ ‪1434/4/16‬هــ؛ املتضمــن أنــه ثبــت لديــه‬\n‫أن مــورث املدعــى عليهــم قــد وهــب شــقيقه املدعــي (‪)000‬كامــل‬\n‫نصيبــه مــن إرثــه مــن أمــه (‪ )000‬مــن هــذا العقــار املذكــور بــدون مقابــل‬\n‫ومبوجبــه فقــد انتقــل نصيبــه املشــاع مــن هــذا العقــار ألخيــه املدعــي‬\n‫وبــه حكــم ؛ كمــا هــو مــدون ومفصــل فيــه ؛ وبدراســة الصــك وصــورة‬\n‫ضبطــه وأوراق املعاملــة قررنــا ‪ :‬التصديــق علــى احلكــم‪ .‬مــع تنبيــه‬\n‫فضيلتــه إلــى أنــه اســتحلف املدعــي علــى مــا يدعيــه وســمى ذلــك ميــن‬\n‫اســتظهار وهــذه اليمــن ال حاجــة لهــا مــع وجــود البينــة املثبتــة للدعــوى‬\n‫وليســت ميــن االســتظهار‪ .‬فيالحــظ هــذا مســتقبالً‪ .‬واهلل املوفـ ـ ـ ـ ـ ـ ــق ؛‬\n\n\n                                                                                       ‫‪250‬‬\n\f      ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪251‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":245,"source_page_end":251,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"eae96b36aa04e0f40d731a30052ef95e846d760346ee135756626d9297d347ed","normalized_text_hash":"8b52d1ed87b84fb561e171a48d6de0593a116e546201836fece1a189d1eacdab","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p245-34189207"},{"id":"2d985a08-fd46-5944-aea8-1d726f436745","document_type":"judgment","category":"judicial","subcategory":"general","title":"هبة -قيام املورث قبل وفاته بإفراغ عقار (هبة) لبعض الورثة- املطالبة بإبطال هذه الهبة وقسمة العقار بن جميع الورثة -تعذر الصلح بن الطرفن -األصل يف التصرفات حملها على الصحة- عدم ثبوت نقص األهلية أو املرض للمورث حن الهبة -ثبوت الهبة للموهوب له مبوت املورث قبل رجوعه -رد الدعوى .","document_number":"3431443","case_number":"32140029","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/6","year":"1434","subject":"هبة -قيام املورث قبل وفاته بإفراغ عقار (هبة) لبعض الورثة- املطالبة بإبطال هذه الهبة وقسمة العقار بن جميع الورثة -تعذر الصلح بن الطرفن -األصل يف التصرفات حملها على الصحة- عدم ثبوت نقص األهلية أو املرض للمورث حن الهبة -ثبوت الهبة للموهوب له مبوت املورث قبل رجوعه -رد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3431443 :‬تاريخه‪1434/2/6:‬هـ‬\n                   ‫رقم الدعوى‪32140029 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34200931‬تاريخه‪1434/4/29 :‬هـ‬\n\n\n‫هبــة ‪ -‬قيــام املــورث قبــل وفاتــه بإفــراغ عقــار (هبــة) لبعــض الورثــة‪-‬‬\n‫املطالبــة بإبطــال هــذه الهبــة وقســمة العقــار بــن جميــع الورثــة‪ -‬تعــذر‬\n‫الصلــح بــن الطرفــن‪ -‬األصــل يف التصرفــات حملهــا علــى الصحــة‪-‬‬\n‫عــدم ثبــوت نقــص األهليــة أو املــرض للمــورث حــن الهبــة‪ -‬ثبــوت الهبــة‬\n                  ‫للموهــوب لــه مبــوت املــورث قبــل رجوعــه‪ -‬رد الدعــوى ‪.‬‬\n\n\n\n‫‪( .1‬األصــل يف التصرفــات حملهــا علــى الصحــة) ينظــر الذخيرة ‪246/6‬‬\n                                                           ‫والفروق ‪.84/2‬‬\n‫‪ .2‬جــاء يف الشــرح الكبيــر ‪( 68/17‬إذا فاضــل بــن ولــده يف العطايــا أو‬\n‫خــص بعضهــم بعطيــة ثــم مــات قبــل أن يســترد ثبــت ذلــك للموهــوب‬\n‫لــه ولــزم وليــس لبقيــة الورثــة الرجــوع هــذا املنصــوص عــن أحمــد‪.)...‬‬\n\n\n\n‫ادعــى بعــض الورثــة علــى زوجــة مورثهــم يطالبــون بإبطــال عطيــة مورثهــم‬\n‫لهــا وألوالدهــا منــه ‪ -‬حيــث إن مورثهــم قبــل وفاتــه بخمســة أشــهر أفــرغ‬\n‫عقــار ًا لهــا وألودهــا منــه ومورثهــم كان مريضـ ًا وقــت اإلفــراغ ومصــاب‬\n‫بجلطــة يف رأســه ‪ -‬أجابــت املدعــى عليهــا باملصادقــة علــى العطيــة وأن‬\n‫مورثهــم عنــد اإلفــراغ كان بكامــل وعيــه وقــد أصيــب بجلطــة يف رأســه‬\n\n                                                                                  ‫‪252‬‬\n\f      ‫ولــم يتأثــر منهــا ســوى أن يــده ثقلــت عليــه وبعــد اإلفــراغ بتســعة أيــام‬\n      ‫أصيــب بجلطــة أخــرى وفقــد احلركــة وأصبــح ينســى أحيانـ ًا وال توافــق‬\n      ‫علــى طلــب املدعــي وذلــك أن مورثهــم أراد أن يفــرغ للمدعــي وأخوتــه‬\n      ‫أرضـ ًا زراعيــة لكنهــم رفضــوا هكــذا أجابــت ‪ -‬صــك ملكيــة العقــار‬\n      ‫مهمــش عليــه لــدى كاتــب العــدل بانتقــال امللكيــة للمدعــى عليهــا‬\n      ‫وأوالدهــا عــن طريــق التنــازل بــدون مقابــل ‪ -‬استفســر ناظــر القضيــة‬\n      ‫مــن املستشــفى عــن حالــة مــورث املدعــن واملدعــى عليهــا عنــد خروجــه‬\n      ‫هــل كانــت مســتعصية يخشــى عليــه مــن املــوت أو مســتقرة ‪ -‬وردت‬\n      ‫اإلفــادة بــأن حالتــه مســتقرة مــع تفصيــل حلالتــه الطبيــة ‪ -‬ومبــا أن‬\n      ‫األصــل يف التصرفــات حملهــا علــى الصحــة ) ينظــر الذخيــرة ‪246/6‬‬\n      ‫والفــروق ‪ - 84/2‬ومبــا أن العطيــة مثبتــة بورقــة رســمية لــدى كاتــب‬\n      ‫العــدل ولــم يثبــت أنــه حــن العطيــة كان ناقــص األهليــة أو مريض ـ ًا‬\n      ‫مرضـ ًا مخوفاً‪،‬ومبــا أن مــورث الطرفــن مــات قبــل رجوعــه عــن عطيتــه‬\n      ‫للمدعــى عليهــم ينظــر الشــرح الكبيــر( ‪ - ) 68/17‬احلكــم بعــدم‬\n      ‫ثبــوت اســتحقاق املدعــن لشــيء مــن العقــار محــل النــزاع ورد دعواهــم‬\n      ‫‪ -‬اعتــرض املدعــي بالئحــة‪ -‬صــدق احلكــم مــن الدائــرة احلقوقيــة‬\n                   ‫السادســة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n      ‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 32140029‬املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 32439772‬وتاريــخ ‪1432/04/24‬ه ـ حضــر املدعــي‬\n\n‫‪253‬‬\n\f‫‪ ........‬حامــل الســجل املدنــي رقــم ‪ ........‬كمــا حضــرت املدعــى عليهــا‬\n‫مصلحــة ‪ ........‬ســجل مدنــي رقــم ‪ ........‬واملعــرف بهــا مــن قبــل ابنهــا‬\n‫متعــب ‪ ........‬ســجل مدنــي رقــم ‪ ........‬وبســؤال املدعــي عــن دعــواه قــال‪:‬‬\n‫إن والــدي قــد تــويف عــام ‪1431‬ه ـ وانحصــر ارثــه يف زوجتــه الباقيــة يف‬\n‫عصمتــه مصلحــه ‪ ........‬ويف أوالده البالغــن املرزوقــن لــه منهــا وهــم‬\n‫‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬ويف أوالده البالغــن ‪........‬‬\n‫و‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬املزوقــن لــه مــن زوجتــه ‪........‬‬\n‫املطلقــة يف حياتــه مبوجــب صــك حصــر اإلرث رقــم ‪19/100/220‬يف‬\n‫‪1432/3/21‬ه ـ الصــادر مــن هــذه احملكمــة وقبــل وفاته بخمســة أشــهر‬\n‫أفــرغ عقــار ًا كائن ـ ًا يف حــارة البلديــة مكون ـ ًا مــن أربعــة أدوار لبعــض‬\n‫الورثــة وهــم زوجتــه ‪ .........‬وأوالدهــا البالغــن املرزوقــن لهــا مــن مورثنــا‬\n‫وهــم ‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬اطلــب إبطــال هــذه‬\n‫العطيــة وقســمة هــذا العقــار بــن جميــع الورثــة حســب القســمة الشــرعية‬\n‫علمـ ًا بــان والــدي كان وقــت اإلفــراغ مريضــا ومصابـ ًا بجلطة يف الرأس‬\n‫هــذه دعــواي ‪ ،‬وبســؤال املدعــي عــن صــك حصــر الورثــة أبــرز صــك ًا‬\n‫صــادرا مــن هــذه احملكمــة برقــم ‪ 19/100/220‬يف ‪1431/3/21‬ه ـ‬\n‫وباالطــاع عليــه وجدتــه طبــق مــا ذكــره يف دعــواه إ‪.‬ه ـ وبســؤاله عــن‬\n‫تاريــخ وفــاة والــده قــال يف ‪1431/2/30‬ه ـ إ‪.‬ه ـ وبســؤاله عــن حالــة والده‬\n‫قبــل الوفــاة قــال إنــه أصيــب بجلطــة وقبــل وفاتــه بثالثــة أشــهر لــم يكــن‬\n‫بكامــل وعيــه وكان ينســى كثيــر ًا هكــذا أجــاب ‪ ،‬ثــم قــال إنــه قبــل‬\n‫اإلفــراغ بثالثــة أشــهر كان ينســى هكــذا قــرر ‪ ،‬وبســؤاله عــن حالــة‬\n‫والــده التــي ذكرهــا هــل كانــت قبــل الوفــاة أو قبــل اإلفــراغ قــال بــل‬\n‫قبــل الوفــاة بثالثــة أشــهر واإلفــراغ مت قبــل شــهرين مــن وفاتــه هكــذا‬\n\n\n                                                                                           ‫‪254‬‬\n\f      ‫أجــاب‪ ،‬وبســؤال املدعــى عليهــا عــن دعــوى املدعــي أجابــت قائلــة إن‬\n      ‫صحــة مــا ورد يف صــك حصــر الورثــة هــو ‪ ....‬بــد ًال مــن ‪ ....‬وأمــا مــا ذكــره‬\n      ‫املدعــي مــن أن مورثنــا قــد أفــرغ عقــار ًا كائن ـ ًا يف حــارة البلديــة لــي‬\n      ‫أنــا وأوالدي ‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬فصحيــح‬\n      ‫إال أن مورثنــا وقــت اإلفــراغ كان بكامــل وعيــه فقــد أصيــب بجلطــة‬\n      ‫يف الــرأس يف شــهر ‪ 6‬عــام ‪1430‬ه ـ ولــم يتأثــر منهــا ســوى أن يــده ثقلــت‬\n      ‫عليــه وأصبــح ميــارس حياتــه بشــكل طبيعــي ثــم يف ‪1430/11/14‬ه ـ أي‬\n      ‫بعــد اإلفــراغ بتســعة أيــام تقريب ـ ًا أصيــب بجلطــة أخــرى وفقــد احلركــة‬\n      ‫وكان ينســى أحيان ـ ًا وال أوافــق علــى طلــب املدعــي وذلــك أن مورثنــا‬\n      ‫أراد إفــراغ مزرعتــه الكائنــة يف أم الزلــة للمدعــي وإخوانــه مــن الزوجــة‬\n      ‫األخــرى فرفضــوا إفراغهــا كمــا أن مورثنــا قــال لــي إننــي ســأعطيهم‬\n      ‫أرض عليهــا وثيقــة كائنــة يف أم الزلــة هكــذا أجابــت ‪ ،‬وبعــرض ذلــك‬\n      ‫ا بــل الصحيــح مــا ذكــرت من أنه وقــت اإلفراغ‬              ‫علــى املدعــي أجــاب قائـ ً‬\n      ‫كان ينســى وأمــا مــا ذكرتــه مــن رفضنــا إفــراغ املزرعــة فرفضنــا ألننــا‬\n      ‫نريــد حظنــا مــن العقــار محــل الدعــوى وكذلــك األرض التــي عليهــا‬\n      ‫ا إننــي أنــا متنــازل عــن نصيبــي يف‬       ‫وثيقــة هكــذا أجــاب ‪ ،‬ثــم قــرر قائـ ً‬\n      ‫العقــار محــل الدعــوى وإمنــا أطالــب بنصيــب موكلــي بقيــة الورثــة ثــم‬\n      ‫أبــرز صــك الوكالــة الصــادر مــن كتابــة العــدل الثانيــة بغــرب مكــة‬\n      ‫برقــم ‪ 420302004238‬يف ‪1430/11/8‬ه ـ املتضمنــة توكيــل كل مــن‬\n      ‫‪ ....‬و‪ ....‬و‪ ....‬أوالد ‪ ........‬ألخيهــم ‪ ........‬وكالــة تخولــه يف الدعــاوي‬\n      ‫واملرافعــات واإلقــرار واإلنــكار وحضــور اجللســات واملدافعــة واملرافعة‪...‬‬\n      ‫إلــخ ‪ ،‬ثــم قــال وأمــا ‪ ........‬و‪ ........‬فلــم يوكلونــي هكــذا قــرر ‪،‬ثــم‬\n      ‫جــرى االطــاع علــى صــك امللكيــة للعقــار محــل النــزاع الصــادر مــن‬\n\n\n‫‪255‬‬\n\f‫كاتــب عــدل مكــة برقــم ‪ 2/124/97‬يف ‪1409/4/7‬ه ـ واملتضمــن‬\n‫ـاء الكائنــة مبكــة املكرمــة‬       ‫( متلــك ‪ ........‬لكامــل الــدار أرض ـ ًا وبنـ ً‬\n‫باملســفلة قــوز النكاســة احملــدودة شــرق ًا ‪ ........‬أمجــد وغرب ـ ًا الرحبــة‬\n‫الكائنــة ثمــه وبهــا دكان علــى الواجهــة وشــام ًا ســكة غيــر نافــذة ومينـ ًا‬\n‫‪ ........‬املذروعــة كاآلتــي ‪ :‬الضلــع الشــمالي أحــد عشــر متــر ًا والشــرقي‬\n‫تســعة أمتــار وعشــرة ســم واجلنوبــي عشــرة أمتــار وخمســون ســم والغربــي‬\n‫ثمانيــة أمتــار وســتون ســم وعــرض الســكة الشــمالية الغيــر نافــذة يف‬\n‫جهتــي الشــرق والغــرب متــر واحــد وخمســة وتســعون ســم ومت بيــع العقــار‬\n‫املذكــور ‪ ........‬بثمــن قــدره مائــة وثمانــون ألــف ريــال ‪ ،‬كمــا وجــد‬\n‫تهميــش أســفل الصــك يتضمــن انتقــال ملكيــة مــا بباطــن الصــك إلــى‬\n‫ملــك كل مــن ‪ ........‬و ‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬وذلــك عــن‬\n‫طريــق التنــازل بــدون مقابــل مقســمة بينهــم حســب الفريضــة الشــرعية‬\n‫للذكــر مثــل حــظ األنثيــن وذلــك حســبما هــو مــدون يف صحيفــة رقــم‬\n‫‪ 8/3189/8‬يف يوم ‪1430/11/5‬هـ ) ‪ ،‬ويف جلسة أخرى حضر املدعي‬\n‫ا عــن‬   ‫وكالــة ‪ ........‬حامــل الســجل املدنــي رقــم ‪ ........‬بصفتــه وكي ـ ً‬\n‫‪ ........‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الثانيــة مبكــة‬\n‫املكرمــة برقــم ‪ 6561‬يف ‪1433/2/15‬هـ ـ والتــي تخولــه حــق املرافعــة‬\n‫واملدافعــة واإلقــرار واإلنــكار والقناعــة باحلكــم وطلــب حتليــف اليمــن‬\n‫‪...‬الــخ‪ ،‬كمــا حضــرت املدعــى عليهــا ‪ ........‬واملعــرف بهــا مــن قبــل‬\n‫ابنهــا احلاضــر معهــا ‪ ........‬كمــا ورد اجلــواب مــن قســم الصلــح برقــم‬\n‫‪32439772‬يف ‪1433/2/24‬هـ ـ واملتضمــن ( تعــذر الصلــح بــن الطرفــن‬\n‫) وبســؤال املدعــي هــل لديــه مــا يثبــت مــا ذكــره موكلــه مــن أن مورثــه‬\n‫كان ناقــص األهليــة حــال اإلفــراغ قــال‪ :‬ال ‪ ،‬ثــم أبــرز تقريــر ًا طبي ـ ًا‬\n\n\n                                                                                         ‫‪256‬‬\n\f      ‫صــادر ًا مــن مستشــفى ‪ ........‬التخصصــي ومترجمـ ًا ترجمــة معتمــدة مــن‬\n      ‫مكتــب ‪ ........‬للترجمــة واملتضمــن حضــور م‪ ........‬يف ‪1430/11/17‬هـ‬\n      ‫ومغادرتــه يف ‪1430/11/20‬ه ـ والتشــخيص النهائــي جلطــة متكــررة ‪،‬‬\n      ‫ويف جلســة أخــرى حضــر الطرفــان وقــد ورد التقريــر الطبــي الصــادر مــن‬\n      ‫مستشــفى النــور التخصصــي برقــم ‪ 48256‬يف ‪1433/9/9‬ه ـ املتضمن (‬\n      ‫فإنــه رد ًا علــى إحالتكــم بشــأن املريــض‪ ........‬ملــف رقــم ‪ 546657‬للــرد‬\n      ‫علــى استفســار فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة حــول‬\n      ‫إذا ما كانت حالة املريض عند خروجه مســتقرة أو مســتعصية يخشــى‬\n      ‫عليــه مــن املــوت ‪ ،‬فإننــا نفيدكــم بــأن املريــض دخــل املستشــفى بتاريــخ‬\n      ‫‪1430/11/17‬ه ـ مــع تاريــخ مرضــي بجلطــة دماغيــة بالفــص األميــن مــن‬\n      ‫الدمــاغ مــع شــلل نصفــي أيســر قبــل خمســة شــهور وكان يعانــي مــن‬\n      ‫شــلل نصفــي أميــن بدرجــة ‪ 5/3‬مــع صعوبــة فهــم وإخــراج الــكالم وعتامة‬\n      ‫يف الرؤيــة بنصــف املجــال البصــري األميــن مــع توتــر وانفعــال نفســي‬\n      ‫واكتئــاب إثــر جلطــة دماغية بالفص األيســر مــن الدماغ ‪ ،‬خرج املريض‬\n      ‫بتاريــخ ‪1430/11/20‬ه ـ بتحســن ويف حالــة عامــة عصبيــة مســتقرة غيــر‬\n      ‫أنــه كان ال يــزال يعانــي مــن األعــراض العصبيــة الناجتــة مــن اجللطــات‬\n      ‫الدماغيــة املتعــددة املتمثلــة يف شــلل رباعــي بدرجــة ‪ 5/3‬مــع صعوبــة فهــم‬\n      ‫وإخــراج الــكالم وعتامــة يف الرؤيــة بنصــف املجــال البصــري األميــن‬\n      ‫مــع توتــر وانفعــال نفســي واكتئــاب والتــي تســتغرق عــادة عــدة شــهور‬\n      ‫وحتتــاج اســتمرار منتظــم علــى العــاج الدوائــي والطبيعــي مــع مراقبــة‬\n      ‫وعنايــة أســرية حتــى ال تنتكــس حالتــه ويتعــرض جللطــات دماغيــة‬\n      ‫إضافيــة أخــرى )إ‪.‬ه ـ ‪،‬وبعرضــه علــى الطرفــن قــرر املدعــي وكالــة‬\n      ‫ا ‪ :‬ال أقــول فيــه شــيئ ًا هكــذا قــرر ‪ ،‬كمــا قــررت املدعــى عليهــا‬  ‫قائ ـ ً‬\n\n\n‫‪257‬‬\n\f‫ـاء علــى‬\n        ‫قائلــة ‪ :‬إن هــذا التقريــر بعــد اجللطــة الثانيــة هكــذا قــررت ‪ ،‬فبنـ ً‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن األصــل يف التصرفــات حملهــا‬\n‫علــى الصحــة ينظــر الذخيــرة ‪ 246/6‬والفــروق ‪ 84/2‬الســيما ومــورث‬\n‫الطرفــن قــد أثبــت عطيتــه بورقــة رســمية لــدى كاتــب العــدل ولــم يثبــت‬\n‫أنــه حــن العطيــة كان ناقــص األهليــة أو مريضـ ًا مرضـ ًا مخوفـ ًا ‪،‬ومبــا‬\n‫أن مــورث الطرفــن مــات قبــل رجوعــه عــن عطيتــه للمدعــى عليهــم قــال‬\n‫يف الشــرح الكبيــر( ‪ ) 68/17‬ط‪/‬التركــي ( إذا فاضــل بــن ولــده يف‬\n‫العطايــا أو خــص بعضهــم بعطيــة ثــم مــات قبــل أن يســترد ثبــت ذلــك‬\n‫للموهــوب لــه ولــزم وليــس لبقيــة الورثــة الرجــوع هــذا املنصــوص عــن‬\n‫أحمــد يف روايــة محمــد بــن احلكــم وامليمونــي واختــاره اخلــال وصاحبــه‬\n‫أبــو بكــر وبــه قــال مالــك والشــافعي وأصحــاب الــرأي وأكثــر أهــل‬\n‫العلــم ‪ ...‬ووجــه الروايــة األولــى قــول أبــي بكــر لعائشــة رضــي اهلل عنهمــا‬\n‫ا ‪ :‬وددت لــو أنــك حزتيــه ‪ .‬فيــدل علــى أنهــا لــو كانــت‬   ‫ملــا نحلهــا نخ ـ ً‬\n‫حازتــه لــم يكــن لهــم الرجــوع ‪ .‬وقــال عمــر ‪ :‬ال نحلــة إال نحلــة يحوزهــا‬\n‫الولــد دون الوالــد ‪ .‬وألنهــا عطيــة لولــده فلزمــت باملــوت كمــا لــو انفــرد‬\n‫وألنــه حــق ألب يتعلــق مبــال الولــد فســقط مبوتــه كاألخــذ مــن مالــه )‬\n‫‪ ،‬لــذا كلــه لــم يثبــت لــدي اســتحقاق املدعــن لشــيء مــن العقــار محــل‬\n‫النــزاع وعليــه فقــد رددت دعــوى املدعــن جتــاه املدعــى عليهــم وأخليــت‬\n‫ســبيلهم مــن هــذه الدعــوى وبــه حكمــت وبعــرض احلكــم علــى املدعــي‬\n‫قــرر عــدم القناعــة وقــررت تســليمهم نســخة مــن صــك احلكــم حــا ًال‬\n‫لالعتــراض عليــه يف مــدة ال تتجــاوز ثالثــن يوم ـ ًا فــإذا انقضــت املــدة‬\n‫ولــم يقدمــوا اعتراضهــم ســقط حقهــم يف االعتــراض واكتســب احلكــم‬\n                     ‫القطعيــة وبــاهلل التوفيــق ‪ .‬حــرر يف ‪ 1434/02/06‬ه ـ‬\n\n\n                                                                                       ‫‪258‬‬\n\f      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ فق ــد ج ــرى‬\n      ‫م ّنــا نح ــن رئيــس واعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n      ‫الصــادر مــن فضيلــة الشــيخ ‪ ........ /‬القاضــي باحملكمــة العامــة مبكــة‬\n      ‫املكرمــة واملســجل بع ــدد ‪ 3431443‬وتاريــخ ‪1434/2/6‬ه ـ املتضمــن‬\n      ‫دعــوى ‪ ........‬ضــد ‪ ، ........‬احملكــوم في ــه مبــا دون باطنــه ‪ ،‬وبدراس ــة‬\n      ‫احلكــم وص ــورة ضبط ــه و الئحتــه االعتراضيــة تق ــررت املوافق ــة عل ــى‬\n      ‫احلكم‪ ،‬واهلل املوفق وصل ــى اهلل عل ــى نبينا محمد وعل ــى آل ــه وصحب ــه‬\n                                                                              ‫وســلم ‪.‬‬\n\n\n\n\n‫‪259‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":252,"source_page_end":259,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"27e04a81e08075e4b9b0a1d9298884ca0a522ab90c0a7ae985315c0536d9bced","normalized_text_hash":"b559f43e1cf82879aa8267351e53df8f159daf54ef0e6313da954c6cfbf27680","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p252-3431443"},{"id":"841d3468-9dea-558f-b804-f81465577a4e","document_type":"judgment","category":"judicial","subcategory":"general","title":"هبة -مستحقات زوجيه -مطالبة زوج إعادة هدايا الزواج وإيجار الشقة وقاعة الفرح -عدم جواز الرجوع يف الهبة -مطالبة الزوج","document_number":"3458940","case_number":"33270955","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/9","year":"1434","subject":"هبة -مستحقات زوجيه -مطالبة زوج إعادة هدايا الزواج وإيجار الشقة وقاعة الفرح -عدم جواز الرجوع يف الهبة -مطالبة الزوج","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3458940 :‬تاريخه ‪1434/3/9 :‬هـ‬\n                  ‫رقم الدعوى ‪33270955:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34275885‬تاريخه ‪1434/7/23:‬هـ‬\n\n\n‫هبــة ‪ -‬مســتحقات زوجيــه ‪ -‬مطالبــة زوج إعــادة هدايــا الــزواج وإيجــار‬\n‫الشــقة وقاعــة الفــرح ‪ -‬عــدم جــواز الرجــوع يف الهبــة ‪ -‬مطالبــة الــزوج‬\n‫ا‬\n‫مبــا خســره يف عقــد النــكاح غيــر مستســاغ وال مقبــول شــرع ًا وال عق ـ ً‬\n‫ا‬‫ـ احلكــم بصــرف النظــر عــن دعــوى املدعــي ‪ -‬محــل الــزواج ليــس محـ ً‬\n                                    ‫للخســارة و الربــح بــل محلــه التوفيــق ‪.‬‬\n\n\n\n‫قولــه صلــى اهلل عليــه وســلم ـ ( العائــد يف هبتــه كالكلــب يقــئ ثــم يعــود‬\n                                                                     ‫يف قيئــه ) ‪.‬‬\n\n\n\n‫ادعــى املدعــي بأنــه كان زوجـ ًا للمدعــى عليهــا وقــد مت فســخ النــكاح‬\n‫بينهما قبل الدخول مقابل عوض دفعته له املرأة ‪ ،‬وقام بإعطاء املدعى‬\n‫عليهــا طقــم ذهــب قيمتــه ‪4860‬ريــال ومجمــوع هدايــا تصــل قيمتهــا‬\n‫خمســة آالف ريال وقيمة اســتئجار قاعة الفرح بـ ‪ 4000‬واســتئجار شــقة‬\n‫مببلــغ ‪ 8125‬ريــال وبحــوزة املدعــى عليهــا صــور لقريبــات املدعــي قامــت‬\n‫بتمزيقهــا وطلــب مــن املدعــى عليهــا التعهــد بعــدم نشــرها وطلــب إعــادة‬\n‫جميــع مــا دفعــه وهــو مبلــغ وقــدره ‪ 21000‬ريــال ‪ -‬مت ســؤال املدعــي هــل‬\n‫الذهــب الــذي أعطــاه للمدعــى عليهــا هــو مــن قبيل الهديــة أم ال ؟ فأجاب‬\n\n\n                                                                                     ‫‪260‬‬\n\f      ‫بقولــه هــو ممــا متعــارف عليــه النــاس وهــو ليــس هديــة ‪ -‬بعــرض الدعــوى‬\n      ‫علــى املدعــى عليهــا صادقــت علــى زواجهــا مــن املدعــي وفســخ نكاحهــا‬\n      ‫منــه وأمــا الذهــب فــكان هديــة منــه والهدايــا األخــرى ال تصــل قيمتهــا‬\n      ‫خمســة آالف ريــال ‪ 5000‬ريــال أمــا مــا ســوى ذلــك فهــي قــد تضــررت‬\n      ‫بإعــادة كامــل املهــر للمدعــي لكونهــا قــد قامــت بصــرف كامــل املهــر‬\n      ‫علــى املالبــس وأغــراض التجميــل قبــل الدخــول وال تســتطيع التصــرف‬\n      ‫بهــا وأمــا الصــور فتعهــدت بعــدم نشــرها وأحضــرت صــور ألهــل املدعــى‬\n      ‫قامــت بتمزيقهــا ونظــر بهــا املدعــي وأحضــرت املدعــى عليهــا ‪CD‬‬\n      ‫وطلبــت مــن املدعــي متزيقــه أمــام القاضــي فقــام املدعــي بأخــذه وقــام‬\n      ‫بكســره يف مجلــس احلكــم ـ ومــن املتعــارف عليــه أن الذهــب املعطــى‬\n      ‫للزوجــة مــن قبــل الــزوج هــو مــن قبيــل الهديــة ـ ومــن املتقــرر شــرع ًا عــدم‬\n      ‫ا بحديــث النبــي صلــى اهلل عليــه وســلم ( العائــد‬      ‫الرجــوع بالهديــة عم ـ ً‬\n      ‫يف هبتــه كالكلــب يقــئ ثــم يعــود يف قيئــه ) ـ ومطالبــة املدعــي مبــا‬\n      ‫خســره مــن العقــد باملدعــى عليهــا غيــر مقبــول وال مستســاغ شــرع ًا وال‬\n      ‫ا للخســارة والربــح بــل محلــه التوفيــق‬   ‫ا حيــث إن الــزواج ليــس محـ ً‬     ‫عقـ ً‬\n      ‫مــن اهلل ـ لــذا مت احلكــم بصــرف النظــر عــن دعــوى املدعــي ـ وقــررت‬\n      ‫املدعــى عليهــا القناعــة وقــرر املدعــي عــدم القناعــة ـ وصــدق احلكــم مــن‬\n                                                                 ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضي يف احملكمــة العامة مبحافظة‬\n      ‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33270955‬وتاريــخ ‪1433/04/18‬‬\n\n‫‪261‬‬\n\f‫ه ـ املقيــدة باحملكمــة برقــم ‪ 33730975‬وتاريــخ ‪ 1433/04/18‬ه ـ‬\n‫ففــي هــذا اليــوم االثنــن املوافــق ‪1434/03/09‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر املدعــي أصالــة مينــي اجلنســية مبوجــب رخصــة إقامــة رقــم‬\n‫وحضــرت حلضــوره املدعــى عليهــا مينيــة اجلنســية مبوجــب إقامــة رقــم‬\n‫وبســؤال املدعــي عــن دعــواه أجــاب قائــا أن املدعــى عليهــا كانــت‬\n‫زوجــة لــي ولــم أدخــل بهــا الدخــول الشــرعي وقــد قــام فضيلتكــم‬\n‫بفســخ نكاحهــا منــي مبوجــب الصــك الصــادر مــن فضيلتكــم برقــم‬\n‫‪ 32297413‬وتاريــخ ‪1432/11/06‬ه ـ علــى عــوض اســتلمته مــن املدعــى‬\n‫عليهــا وقــدره خمســة وعشــرون ألــف ريــال وقــد قمــت بإعطــاء املدعــى‬\n‫عليهــا طقــم ذهــب قيمتــه أربعــة آالف وثالثمائــة وســتون ريــاال ومجموعــة‬\n‫هدايــا قيمتهــا خمســة آالف ريــال وقمــت باســتئجار قاعــة أفــراح مببلــغ‬\n‫قــدره أربعــة آالف ريــال واســتأجرت شــقة مببلــغ قــدره ثمانيــة آالف ومائة‬\n‫وخمســة وعشــرون ريــاال وبحــوزة املدعــى عليهــا صــور لقريباتــي علمــت‬\n‫أنهــا قامــت بتمزيقهــا أطلــب تعهدهــا بعــدم نشــر أي منهــا وإلزامهــا بدفــع‬\n‫مــا أعطيتهــا ومــا تكفلــت بــه مــن اخلســائر الــواردة أعــاه ومجمــوع‬\n‫جميــع ذلــك مبلغــا قــدره واحــد وعشــرون ألــف ريــال وبســؤال املدعــي‬\n‫عــن الذهــب بــأي صفــة قــام بإعطائــه للمدعــى عليهــا هــل هــو هديــة أم‬\n‫مــاذا فأجــاب قائــا أن هــذا ممــا هــو متعــارف عليــه عنــد امللكــة تقــدمي‬\n‫طقــم ذهــب للزوجــة وبســؤاله هــل هــو هديــة فأجــاب قائــا ليســت هديــة‬\n‫وبســؤال املدعــى عليهــا عمــا جــاء يف دعــوى املدعــي أجابــت قائلــة مــا‬\n‫ذكــره املدعــي مــن شــأن الــزواج وعــدم الدخــول وفســخ النــكاح فذلــك‬\n‫كلــه صحيــح وأمــا مــا ذكــره ســوى ذلــك فالذهــب كان هديــة مــن‬\n‫املدعــي والهدايــا األخــرى ال تصــل قيمتهــا خمســة آالف ريــال وأمــا مــا‬\n\n\n                                                                                    ‫‪262‬‬\n\f      ‫ســوى ذلــك فأنــا قــد تضــررت كذلــك بإعادتــي كامــل املهــر عندمــا مت‬\n      ‫احلكــم بإلزامــي بإعادتــه للمدعــي وذلــك لكونــي قــد قمــت بصــرف‬\n      ‫كامــل املهــر لشــراء مالبــس وأغــراض التجميــل قبــل الدخــول وجميــع‬\n      ‫ذلــك يف املنــزل ال أســتطيع التصــرف بــه وأمــا مــا يتعلــق بالصــور فأنــا‬\n      ‫أتعهــد اآلن أمــام فضيلتكــم بعــدم نشــري ألي صــورة عائــدة ألهلــه وقــد‬\n      ‫أحضــرت معــي صــور قمــت بتمزيقهــا عائــدة ألهــل املدعــي فأبرزتهــا‬\n      ‫ونظــر بهــا املدعــي وأحضــرت املدعــى عليهــا ‪ cd‬وقالــت أن بداخلــه‬\n      ‫صــورة عائــدة ألهلــي وأهــل املدعــي وأطلــب مــن املدعــي متزيقــه أمامكــم‬\n      ‫فأخــذه املدعــي وقــام بكســره يف مجلــس احلكــم هكــذا أجابــت فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث إن املدعــي يطلــب اســترداد‬\n      ‫مــا قــام بتســليمه للمدعــى عليهــا عنــد عقــد قرانــه بهــا مــن قيمــة الذهــب‬\n      ‫والهدايــا ودفــع مــا خســره مــن فســخ النــكاح مــن أجــرة القاعــة والشــقة‬\n      ‫وحيــث إن املدعــى عليهــا قــد دفعــت بامتــاك الهديــة وخســارتها كذلك‬\n      ‫مــن إعــادة كامــل املهــر للمدعــي بعــد التصــرف بــه وحيــث إمنــا يظهــر‬\n      ‫ممــا هــو متعــارف عليــه أن الذهــب املعطــى للزوجــة مــن قبــل الــزوج هــو‬\n      ‫مــن قبيــل الهديــة وحيــث إن مــن املتقــرر شــرعا عــدم جــواز الرجــوع يف‬\n      ‫الهديــة عمــا مبــا جــاء يف حديــث النبــي صلــى اهلل عليــه وســلم أنــه قــال‪:‬‬\n      ‫( العائــد يف هبتــه كالكلــب يقــيء ثــم يعــود يف قيئــه ) وحيث إن مطالبة‬\n      ‫املدعــي مبــا خســره مــن العقــد باملدعــى عليهــا غيــر مقبــول وال مستســاغ‬\n      ‫شــرعا وال عقــا وحيــث إن محــل الــزواج ليــس محــا للخســارة والربــح‬\n      ‫املــادي بــل محلــه التوفيــق مــن اهلل جلميــع مــا تقــدم فقــد حكمــت بصرف‬\n      ‫النظــر عــن دعــوى املدعــي وبعــرض احلكــم علــى الطرفــن قــرر املدعــي‬\n      ‫عــدم القناعــة وقــررت املدعــى عليهــا القناعــة باحلكــم وأقفلــت اجللســة‬\n\n\n‫‪263‬‬\n\f‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                           ‫وســلم ‪ .‬حــرر يف ‪1434/03/09‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 33/730975‬وتاريــخ‬\n‫‪1434/08/01‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪ 33/730975‬وتاريــخ‬\n‫‪1434/08/03‬ه ـ واملصدقــة مــن الدائــرة احلقوقيــة الثانيــة لألحــوال‬\n‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة‬\n‫االســتئناف مبكــة املكرمــة بالقــرار الصــادر مــن أصحــاب الفضيلــة‬\n‫قضــاة محكمــة االســتئناف رقــم ‪ 34275885‬وتاريــخ ‪1434/07/23‬ه ـ‬\n‫املتضمــن مــا نصــه ‪ :‬وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة‬\n‫علــى احلكــم وبــاهلل التوفيــق ‪.‬أ‪.‬ه ـ ‪ ،‬قاضــي اســتئناف ختــم وتوقيــع‬\n‫وقاضــي اســتئناف ختــم وتوقيــع ورئيــس الدائــرة ختــم وتوقيــع ‪ ،‬عليــه‬\n‫فقــد أمــرت بإحلــاق ذلــك بالضبــط وســجله وبــاهلل التوفيــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/08/07‬ه ـ ‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة‬\n‫مكــة املكرمــة االطــاع علــى الصــك الصــادر مــن فضيلة الشــيخ‪....... /‬‬\n‫القاضــي باحملكمــة العامــة بجــدة برقــم ‪ 3458940‬وتاريــخ‪1434/3/9‬‬\n‫ه ـ املتضمــن دعــوى‪ ...... /‬ضــد‪ ........ /‬وبدراســة الصــك وصــورة ضبطــه‬\n‫تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                   ‫وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                   ‫‪264‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":260,"source_page_end":264,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4d0fdb22c905b0e139c8a532d40aa51ec946ba09feed4a514d9b4ca39a4ffef2","normalized_text_hash":"68b6b9ce5911f8b1bd608d03d4276aef6586ea696b2ca355c4e8573605c7dbb2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p260-3458940"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

